  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Restaurace: Bistro Subcarpați (Curtea de Argeș)', 'Oblíbené bistro v Curtea de Argeș u jižního začátku Transfăgărășanu, ideální na doplnění sil před náročným výjezdem. Nabízí poctivou rumunskou i mezinárodní kuchyni na krásné terase s přátelskou obsluhou. S hodnocením kolem 4,7 hvězdičky patří k nejlépe hodnoceným podnikům ve městě a je stálicí mezi motorkáři.', 45.1391, 24.6767, 'https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Curtea%20de%20Arges%20monastery.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Argesului,%20Curtea%20de%20Arges,%20AG.jpg"}'::text[], 0),
    (v_route, 'Přehrada Vidraru (Lacul Vidraru)', 'Mohutná obloukovitá přehrada z roku 1966 zadržuje jezero Vidraru sevřené v horách Fagaraš. Na hrázi vysoké přes 160 metrů stojí socha Prométhea a otevírá se odtud dech beroucí výhled na jižní část Transfăgărășanu. Ideální první zastávka na motorce, kde si dáte pauzu a vychutnáte panorama.', 45.363, 24.634, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Dam%20in%20Romania.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vidraru%20Prometheus.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Vidraru.jpg"}'::text[], 1),
    (v_route, 'Hrad Poenari (Drákulův hrad)', 'Zřícenina pevnosti Poenari trůní vysoko na skalním ostrohu nad údolím řeky Arges a je spojována s vládcem Vladem Napichovačem, předobrazem hraběte Drákuly. K hradu vede přes 1400 schodů, odměnou je ale úchvatný výhled do kraje. Pro milovníky historie a legend nezapomenutelná odbočka hned na začátku trasy.', 45.352, 24.635, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Poenari%20-%20vedere%20principala.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Poenari%20-%20vedere%20principala.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Poenari%20Castle%20(Citadel).jpg"}'::text[], 2),
    (v_route, 'Tunel Bâlea', 'Tunel Bâlea dlouhý 887 metrů je nejvyšší silniční tunel v Rumunsku a označuje nejvyšší bod celé trasy pod hřebenem Fagaraše. Je nasvícený jen slabě, uvnitř bývá chladno a vlhko, proto dbejte zvýšené opatrnosti. Za jižním portálem vás čeká legendární výhled na kaskádu serpentin klesajících do údolí.', 45.596, 24.617, 'https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan%20near%20Balea%20lake.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Transfagarasan-north.JPG"}'::text[], 3),
    (v_route, 'Jezero Bâlea (Bâlea Lac)', 'Ledovcové jezero Bâlea leží ve výšce 2034 metrů přímo v srdci nejvyšší části Transfăgărășanu. Kolem se rozkládají skalnaté štíty a horské louky, u břehu stojí chata i restaurace – dokonalé místo na zastávku a fotku motorky s alpskou kulisou. V zimě zde dokonce staví ledový hotel.', 45.604, 24.617, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Balea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Balea%20lake%20and%20chalet.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/RO%20B%20Transfagarasan%20view%20towards%20the%20north%20from%20Balea%20Lake%202.jpg"}'::text[], 4),
    (v_route, 'Vodopád Bâlea (Cascada Bâlea)', 'Nejvyšší vodopád v pohoří Fagaraš padá z výšky kolem 60 metrů po skalní stěně pod jezerem Bâlea. Nachází se na severní straně silnice a k jeho úpatí se dostanete krátkou procházkou nebo lanovkou. Skvělá zastávka na osvěžení uprostřed serpentin.', 45.618, 24.622, 'https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Enchanted%20Balea%20falls.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Telecabina%20B%C3%A2lea%20Lac%20%E2%80%93%20B%C3%A2lea%20Cascad%C4%83.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Furkapass', 'Furka je s výškou 2429 m nejvyšší z trojice průsmyků a spojuje kantony Uri a Wallis. Silnice plná dramatických vlásenek se proslavila i díky honičce z bondovky Goldfinger. Z vrcholu se otevírají velkolepé výhledy do údolí Rhôny.', 46.572, 8.415, 'https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Furkapass_Westseite.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Wallis_Furkapass_Blick_auf_den_Grimselpass_3.JPG"}'::text[], 0),
    (v_route, 'Ledovec Rhône a Belvédère', 'Přímo u serpentin na západní straně Furky leží ledovec Rhône, pramen řeky Rhôny, s legendární ledovou jeskyní vysekanou do jeho boku. Historický hotel Belvédère je ikonickým bodem trasy a ideálním místem na zastávku a fotky.', 46.573, 8.389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhonegletscher_Furkapass_15092011.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rhonegletscher_Furkapass_15092011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Furka-h%C3%A1g%C3%B3,_kil%C3%A1t%C3%A1s_a_Belvedere_Hotelt%C5%91l_a_Rh%C3%B4ne_v%C3%B6lgy%C3%A9re._Fortepan_17778.jpg"}'::text[], 1),
    (v_route, 'Grimselpass', 'Grimsel (2164 m) spojuje údolí Rhôny s Bernskou vysočinou a proslul soustavou přehradních jezer s tyrkysovou vodou. U vrcholu leží jezera Totensee a Grimselsee, obklopená holými žulovými skalami. Krajina působí drsně a měsíčně, což z průsmyku dělá nezapomenutelný zážitek.', 46.561, 8.333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grimselpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/C5.18_Totensee,_Hotel_Grimselpass.jpg"}'::text[], 2),
    (v_route, 'Sustenpass', 'Susten (2224 m) je považován za nejlépe stavěnou z trojice silnic – široké, plynulé zatáčky s dokonalým výhledem na ledovec Stein. Průsmyk spojuje kantony Uri a Bern a nabízí jednu z nejplynulejších jízd v celém okruhu. Krátký tunel pod vrcholem odděluje obě strany hor.', 46.7267, 8.446, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sustenpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/View_from_S%C3%BCstenpass.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Ochsen (Andermatt)', 'Tradiční švýcarská restaurace v centru Andermattu, ideální zastávka před náročným okruhem nebo po jeho dokončení. Podává poctivé alpské speciality jako fondue a rösti v útulném prostředí. S hodnocením kolem 4,6 patří k nejlépe hodnoceným podnikům ve městě.', 46.6355, 8.5945, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG"}'::text[], 4),
    (v_route, 'Andermatt', 'Andermatt je horské městečko v kantonu Uri, ideální výchozí i cílový bod celého okruhu. Leží na křižovatce alpských cest a nabízí ubytování, benzínky i restaurace před náročnou jízdou. Odtud se dá pokračovat i na další slavné průsmyky jako Oberalp či Gotthard.', 46.6353, 8.5941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Rathaus.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Andermatt_Nosenhaus.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kölnbreinsperre – přehrada v údolí Maltatal', 'Impozantní klenbová přehrada vysoká 200 m je nejvyšší přehradou Rakouska a leží na konci úchvatné Malta Hochalmstraße plné tunelů a serpentin. Za tyrkysovou hladinou vodní nádrže se tyčí ledovcové štíty národního parku Vysoké Taury. Na koruně přehrady čeká vyhlídková plošina Airwalk a horský hotel s panoramatickou restaurací.', 47.078, 13.352, 'https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%B6lnbreinsperre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Airwalk%20K%C3%B6lnbrein%20Staumauer,%20Maltatal,%20K%C3%A4rnten.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/1024%20Malta%20Hochalmstra%C3%9Fe,K%C3%B6lnbrein%20Stausee-3126.jpg"}'::text[], 0),
    (v_route, 'Innerkrems', 'Malebná horská osada ve výšce zhruba 1480 m tvoří severní vstupní bránu na Nockalmstraße. Je to ideální místo na natankování, kávu a poslední zastávku před výjezdem do serpentin. V okolí se rozkládá lyžařské a turistické středisko obklopené vrcholky Nockbergů.', 46.929, 13.688, 'https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems%20Krems%20in%20K%C3%A4rnten%2020070910a.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Innerkrems%20Krems%20in%20K%C3%A4rnten%2020070910a.jpg"}'::text[], 1),
    (v_route, 'Nockalmstraße – panoramatická silnice', 'Placená horská silnice dlouhá 34 km, která se klikatí 52 vlásenkami napříč jemně zaoblenými horami Nockberge. Pro motorkáře je to jeden z nejkrásnějších alpských zážitků – plynulé zatáčky, minimální provoz a nekonečné výhledy na travnaté kopce. Silnice je sjízdná od začátku května do konce října, mýto pro motorky je zhruba 18,50 €.', 46.885, 13.7, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse-Karlbad.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/K%C3%A4rnten%20Nockalmstra%C3%9Fe%2012.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Windebensee%2026082007%2061.jpg"}'::text[], 2),
    (v_route, 'Eisentalhöhe – nejvyšší bod 2042 m', 'Nejvyšší bod celé Nockalmstraße ležící ve výšce 2042 m nad mořem. Z parkoviště se otevírá kruhový panoramatický výhled na hřebeny Nockbergů a v jasném počasí i na vzdálené vrcholy Vysokých Taur. Pro motorkáře je to povinná fotozastávka na střeše celé trasy.', 46.883, 13.7, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Eisentalhoehe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nockalmstrasse%20Eisentalhoehe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nockberge%20Eisentalh%C3%B6he%20Panorama%2001.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Seerestaurant 1884 (Millstatt am See)', 'Michelinská restaurace v historické vile See-Villa přímo na břehu jezera Millstätter See s terasou sahající až k vodní hladině. Kuchyně staví na čerstvě ulovených rybách z jezera, zvěřině z vlastního revíru a vínech z vlastní vinice. Na TripAdvisoru má vynikající hodnocení 4,7 z 5 a je oceněna hvězdou průvodce Michelin – ideální odměna po náročné jízdě horami.', 46.8047, 13.5797, 'https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg"}'::text[], 4),
    (v_route, 'Millstätter See', 'Druhé největší korutanské jezero a nejobjemnější svého druhu s hloubkou až 142 m. Teplá tyrkysová voda a klidné pobřeží z něj dělají ideální místo na oddech, koupání a kávu před nebo po náročné jízdě horami. Okolní silnice kolem jezera nabízejí příjemnou vyjížďku bez dálnic.', 46.7903, 13.5745, 'https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Millstatt%20am%20Millstaetter%20See%20und%20Rei%C3%9Feck%2008112015%208850.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Millst%C3%A4tter%20See%20Bootsverleih.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Baden-Baden', 'Elegantní lázeňské město na severním okraji Černého lesa a startovní bod Schwarzwaldhochstraße. Reprezentativní kolonáda Trinkhalle a Kurhaus dávají tušit dávnou noblesu evropské smetánky. Ideální místo na kávu a natankování před stoupáním do hor.', 48.761, 8.241, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baden_Baden_-_Trinkhalle_-_View_SSE_I.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Baden-Baden-Trinkhalle-aussen-Ost3-gje.JPG"}'::text[], 0),
    (v_route, 'Mummelsee', 'Malebné ledovcové horské jezero ve výšce přes 1000 m přímo u silnice B500 pod vrcholem Hornisgrinde. Opředené pověstí o vodních vílách, s horským hotelem a stánky – oblíbená motorkářská zastávka. Skvělé místo na fotku i krátký odpočinek s výhledem na hladinu jezera.', 48.593, 8.207, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mummelsee%20und%20Hotel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mummelsee%20und%20Hotel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Seebach%20-%20Schwarzwaldhochstra%C3%9Fe%20-%20Mummelsee%20%2B%20Berghotel%20Mummelsee%2004%20ies.jpg"}'::text[], 1),
    (v_route, 'Ruhestein', 'Horské sedlo a vstupní brána do Národního parku Černý les s návštěvnickým centrem a hospodou Ruhestein-Schänke. Křižovatka turistických tras nad divokým jezerem Wildsee. Příjemná zastávka na občerstvení uprostřed hřebenové jízdy.', 48.56, 8.22, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ruhestein-Nationalparkzentrum-02-2022-gje.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ruhestein-Nationalparkzentrum-02-2022-gje.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nationalpark%20Schwarzwald.JPG"}'::text[], 2),
    (v_route, 'Schliffkopf', 'Jeden z nejvyšších bodů na trase (1055 m) s otevřenými vřesovišti a širokými výhledy do kraje. Vrchol leží v Národním parku Černý les a v okolí najdete horský hotel i vyhlídkové trasy. Za jasného počasí dohlédnete daleko přes zalesněné hřebeny.', 48.535, 8.216, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sonnenuntergang%20am%20Schliffkopf%2C%20Nationalpark%20Schwarzwald.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sonnenuntergang%20am%20Schliffkopf%2C%20Nationalpark%20Schwarzwald.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Gasthof Rosengarten (Baiersbronn)', 'Tradiční hotelová restaurace v obci Baiersbronn, která je proslulá největší koncentrací michelinských hvězd v Německu. Kuchyně staví na poctivé regionální a bádensko-švábské klasice a nabízí skvělý poměr ceny a kvality. Hosté ji hodnotí výborně (4,5/5) a chválí chutná jídla i příjemnou obsluhu.', 48.503, 8.371, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Baiersbronn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Baiersbronn.jpg"}'::text[], 4),
    (v_route, 'Freudenstadt', 'Cílové město trasy proslulé největším tržním náměstím v Německu, obklopeným podloubími a měšťanskými domy. Ideální místo na oběd a odpočinek po projetí hřebenovky. Odtud se dá pohodlně pokračovat dál do jižního Černého lesa.', 48.463, 8.411, 'https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt%20-%20Marktplatz%20Kirche.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt%20-%20Marktplatz%20Kirche.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Freudenstadt.jpg"}'::text[], 5);
