  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bastia', 'Přístavní metropole severní Korsiky a přirozený start i cíl okruhu. Zaparkuj u Vieux Port, dej si kávu a nasaj atmosféru starých uliček citadely. Odsud vyrážíš na severní smyčku kolem Cap Corse – natankuj do plna, dál na mysu jsou pumpy vzácné.', 42.69729, 9.45088, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bastia%20vieux%20port.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bastia%20vieux%20port.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bastia-le-vieux-port.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corse-04518-bastia-vieux%20port.jpg"}'::text[], 0),
    (v_route, 'Cap Corse', 'Divoký severní poloostrov s úzkou pobřežní silnicí D80, která se lepí na útesy nad mořem. Nekonečné serpentiny, janovské věže a rybářské vesničky odměňují každou zatáčku výhledem. Silnice je místy jen na jedno auto, takže jeď defenzivně a užívej si jeden z nejkrásnějších pobřežních úseků ostrova.', 42.964, 9.447, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cap%20Corse%20-%20on%20the%20D80%20after%20Albo%20Punta%20di%20Canelle%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cap%20Corse%20-%20on%20the%20D80%20after%20Albo%20Punta%20di%20Canelle%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corse-04642-marine%20de%20Giottani-%20cap%20Corse.jpg"}'::text[], 1),
    (v_route, 'Calvi', 'Přímořské město v Balagne s mohutnou janovskou citadelou nad tyrkysovým zálivem. Ideální zastávka na konci prvního dne – marina, pláž a spousta restaurací. Odsud druhý den zamíříš do hor přes klikaté silnice regionu Balagne.', 42.566, 8.7571, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Calvi%20-%20Punta%20San%20Francesco%20-%20Quartiers%20de%20la%20Citadelle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20Calvi%20-%20Punta%20San%20Francesco%20-%20Quartiers%20de%20la%20Citadelle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Citadel%20of%20Calvi,%20Corsica,%20France%20(52724224695).jpg"}'::text[], 2),
    (v_route, 'Col de Vergio', 'Nejvýše položený sjízdný průsmyk Korsiky (1478 m) na silnici D84 mezi Niolem a údolím Porto. Cesta nahoru vede borovicovými lesy Aïtone a plná serpentin nabízí famózní výhledy do hor. Nahoře je chladno i v létě, tak si přibal vrstvu navíc.', 42.29032, 8.8784, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bocca%20di%20Verghju.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bocca%20di%20Verghju.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corsica,%20Col%20de%20Vergio,%20Jesus%20Christus.jpg"}'::text[], 3),
    (v_route, 'Corte', 'Historické srdce Korsiky s citadelou na skále, obklopené horami. Univerzitní město je skvělou základnou pro průzkum vnitrozemí a soutěsek. Zastav se na náměstí, dej si korsickou specialitu a naber sílu před cestou do Restonicy.', 42.30941, 9.14902, 'https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parc%20Hte%20Corse-Bozio-Corte3.JPG"}'::text[], 4),
    (v_route, 'Restaurace: A Casuccia (Corte)', 'Rodinná restaurace v srdci Corte na terase pod historickým sídlem generála Gafforiho, ideální zastávka na konci druhého dne. Na jídelníčku najdeš pravé korsické speciality i vyhlášené pizzy z místních surovin. Skvělé hodnocení kolem 4,5 hvězdy chválí přátelskou obsluhu, výhled z terasy a poctivé porce za rozumnou cenu.', 42.3051, 9.1512, 'https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/GR20%20DEPUIS%20CORTE%20(CORSE%20-%20FRANCE).jpg"}'::text[], 5),
    (v_route, 'Restonica', 'Dramatická horská soutěska nad Corte s křišťálovou řekou a žulovými stěnami. Úzká silnice D623 stoupá údolím k horským jezerům – jeď opatrně, je vyhrazená a v sezoně plná turistů. Odměnou je jedno z nejfotogeničtějších údolí ostrova.', 42.225, 9.05, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gorge%20de%20Restonica01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gorge%20de%20Restonica01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Korsika%20Corte%20Restonica%20Tal%202.jpg"}'::text[], 6),
    (v_route, 'Les Calanche de Piana', 'Bizarní červené žulové skály nad Portským zálivem, zapsané v UNESCO. Silnice D81 se proplétá přímo mezi rozeklanými skalními věžemi nad mořem – jeden z nejikoničtějších úseků na Korsice. Zastav na vyhlídce, ale pozor na úzkou vozovku a protijedoucí autobusy.', 42.238, 8.6363, 'https://commons.wikimedia.org/wiki/Special:FilePath/01%20Calanche%20Piana.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/01%20Calanche%20Piana.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/02%20Calanche%20Piana.jpg"}'::text[], 7),
    (v_route, 'Ajaccio', 'Hlavní město Korsiky a rodiště Napoleona, ležící v širokém zálivu. Živá marina, palmové promenády a spousta míst na přenocování z něj dělají příjemnou zastávku na konci třetího dne. Odsud vyrážíš na jižní cíp ostrova.', 41.9267, 8.7369, 'https://commons.wikimedia.org/wiki/Special:FilePath/Port%20Ajaccio.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Port%20Ajaccio.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Citadelle%20d''Ajaccio.jpg"}'::text[], 8),
    (v_route, 'Bonifacio', 'Středověké město dramaticky posazené na bílých vápencových útesech nad mořem na nejjižnějším cípu ostrova. Přístup vede po klikaté pobřežní silnici s výhledy až na Sardinii. Nech motorku dole a projdi se úzkými uličkami horního města – zážitek k nezaplacení.', 41.3874, 9.15941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG"}'::text[], 9),
    (v_route, 'Restaurace: Les Quatre Vents (Bonifacio)', 'Elegantní restaurace na konci nábřeží bonifacké mariny s terasou přímo nad přístavem a výhledem na citadelu. Specializuje se na ryby a mořské plody – domácí bouillabaisse i lingvine s humrem, v zimě přechází na tradiční korsickou kuchyni. Vynikající hodnocení 4,6 hvězdy chválí čerstvé suroviny, kvalitu a nezapomenutelnou polohu u vody.', 41.3877, 9.1594, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bonifacio%20cliffs%20-Le%20Grain%20de%20Sable.JPG"}'::text[], 10),
    (v_route, 'Porto-Vecchio', 'Elegantní přístavní město na jihovýchodě, obklopené proslulými plážemi Palombaggia a Santa Giulia. Skvělé místo na oběd u mariny před tím, než zamíříš do hor k průsmyku Bavella. Staré město na kopci nabízí příjemný stín a výhled na záliv.', 41.59101, 9.27947, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Palombaggia%20Beach,%20Corsica,%20France%20(52724214180).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Palombaggia%20Beach,%20Corsica,%20France%20(52724214180).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Plage%20marina%20fiori%20-%20panoramio.jpg"}'::text[], 11),
    (v_route, 'Col de Bavella', 'Legendární horský průsmyk (1218 m) s pilovitými skalními jehlami Aiguilles de Bavella, sen každého motorkáře. Silnice D268 k němu je jedna souvislá série dokonalých serpentin borovicovými lesy. Nahoře zastav u vyhlídky a vychutnej si panorama – tohle je vrchol celého okruhu.', 41.79602, 9.22477, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aiguilles%20de%20Bavella,%20Corsica.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aiguilles%20de%20Bavella,%20Corsica.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zonza%20-%20Aiguilles%20Bavella.jpg"}'::text[], 12);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Cangas de Onís', 'Historické městečko, první hlavní město asturského království, je ideálním startem okruhu. Přes řeku Sella se klene fotogenický „římský" most s křížem Vítězství, symbol Asturie. Zaparkujte, dejte si kávu a načerpejte síly před stoupáním do hor. V okolí najdete i poslední benzinky před horskými úseky.', 43.3513, -5.1285, 'https://commons.wikimedia.org/wiki/Special:FilePath/Congas%20de%20Onis.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Congas%20de%20Onis.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Puente%20Romano.JPG"}'::text[], 0),
    (v_route, 'Svatyně Covadonga', 'Neorománská bazilika Santa María la Real se tyčí na skále nad údolím a je duchovním srdcem Asturie. Vedle stojí posvátná jeskyně Santa Cueva s Pannou Marií Covadonžskou. Cesta sem stoupá lesem v pěkných zatáčkách. Je to skvělé místo na zastávku před náročným výjezdem k jezerům.', 43.30886, -5.05352, 'https://commons.wikimedia.org/wiki/Special:FilePath/Covadonga%20-%20Bas%C3%ADlica%20de%20Santa%20Mar%C3%ADa%20la%20Real%2009.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Covadonga%20-%20Bas%C3%ADlica%20de%20Santa%20Mar%C3%ADa%20la%20Real%2009.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bas%C3%ADlica%20de%20Santa%20Mar%C3%ADa%20la%20Real%20de%20Covadonga,%20Asturias.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Santuario%20de%20Covadonga.%20Santa%20Cueva.jpg"}'::text[], 1),
    (v_route, 'Lagos de Covadonga', 'Dvě ledovcová jezera Enol a Ercina leží ve výšce přes 1000 metrů uprostřed pastvin a vápencových štítů. Silnice sem je úzká, prudká a plná serpentin – v sezoně bývá pro auta regulovaná, ale motorky mají obvykle volno. Nahoře na vás čeká jeden z nejkrásnějších horských výhledů Španělska. Pozor na krávy a mlhu, která přichází rychle.', 43.26992, -4.98615, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Enol%20(Lagos%20de%20Covadonga,%20Picos%20de%20Europa,%20Asturias,%20Espa%C3%B1a).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Enol%20(Lagos%20de%20Covadonga,%20Picos%20de%20Europa,%20Asturias,%20Espa%C3%B1a).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lago%20Ercina%20(Lagos%20de%20Covadonga,%20Picos%20de%20Europa,%20Asturias,%20Espa%C3%B1a)%2004.JPG"}'::text[], 2),
    (v_route, 'Mirador del Fitu', 'Vyhlídka ve výšce 1100 metrů v pohoří Sueve nabízí panoramatický výhled na Picos de Europa i asturské pobřeží. Přístupová silnice je jedna dlouhá řada zatáček, kterou milují motorkáři i cyklisté. Za jasného dne odsud vidíte moře i zasněžené štíty najednou. Ideální místo na fotku motorky s horami v pozadí.', 43.43907, -5.19347, 'https://commons.wikimedia.org/wiki/Special:FilePath/ES1200043-Sierra%20del%20Sueve%20desde%20el%20Mirador%20del%20Fito%20IGP0291.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/ES1200043-Sierra%20del%20Sueve%20desde%20el%20Mirador%20del%20Fito%20IGP0291.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/ES1200043-Sierra%20del%20Suava%20desde%20el%20Mirador%20del%20Fito%20AGA9989.jpg"}'::text[], 3),
    (v_route, 'Desfiladero de los Beyos', 'Jedna z nejužších průjezdných soutěsek Evropy, vyhloubená řekou Sella podél silnice N-625. Skalní stěny se tu zvedají stovky metrů kolmo nad hlavou a silnice se vine těsně u řeky. Jízda soutěskou je nezapomenutelný zážitek, ale buďte opatrní – je tu stín, vlhko a místy kluzký asfalt. Rozhodně žádná dálnice, jen čistá horská romantika.', 43.3, -5.03, 'https://commons.wikimedia.org/wiki/Special:FilePath/Desfiladero%20de%20los%20Beyos%20o%20del%20Sella%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Desfiladero%20de%20los%20Beyos%20o%20del%20Sella%20-%20panoramio.jpg"}'::text[], 4),
    (v_route, 'Potes', 'Malebné kamenné městečko je srdcem údolí Liébana a přirozeným místem k přenocování při dvoudenním okruhu. Úzké uličky, středověké mosty přes řeku Quiviesa a věž Torre del Infantado tvoří kulisu jako z pohádky. Najdete tu spoustu restaurací s místní kuchyní a likérem orujo. Odsud vyrážejí trasy k lanovce Fuente Dé i přes průsmyk San Glorio.', 43.15368, -4.62343, 'https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2016.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2016.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Torre%20del%20Infantado%20(Potes)%20(2660853032)%20(2).jpg"}'::text[], 5),
    (v_route, 'Restaurace: Casa Cayo (Potes)', 'Tradiční rodinná restaurace v samém srdci Potes je legendou lebanské kuchyně a ideální zastávkou v půlce okruhu. Ochutnáte tu proslulý cocido lebaniego, jehněčí i místní sýry a k tomu domácí likér orujo. Hosté ji milují za skvělou kvalitu i vřelý přístup – hodnocení kolem 4,5 hvězdy na TripAdvisoru a 4,6 na Googlu z ní dělá jednu z nejoblíbenějších adres ve městě.', 43.1548, -4.6222, 'https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2041.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Potes,%20Cantabria%2041.jpg"}'::text[], 6),
    (v_route, 'Fuente Dé', 'Slepé údolí končí kolmou vápencovou stěnou, kde lanovka vyveze návštěvníky o 750 metrů výš k vyhlídce Mirador del Cable ve výšce 1850 metrů. Silnice CA-185 sem z Potes vede krásným lebanským údolím plným zatáček. Nechte motorku dole a vyjeďte lanovkou za dechberoucím výhledem na Picos de Europa. Nahoře bývá výrazně chladněji, přibalte si vrstvu navíc.', 43.1465, -4.81451, 'https://commons.wikimedia.org/wiki/Special:FilePath/Telef%C3%A9rico%20de%20Fuente%20D%C3%A9.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Telef%C3%A9rico%20de%20Fuente%20D%C3%A9.jpg"}'::text[], 7),
    (v_route, 'Puerto de San Glorio', 'Vysoký horský průsmyk ve výšce 1604 metrů spojuje Kantabrii s provincií León a tvoří velkolepé finále okruhu. Silnice se vine dlouhými, přehlednými serpentinami s minimem provozu – motorkářský sen. Z vrcholu vede krátká odbočka k vyhlídce Mirador de Llesba se sochou medvěda a výhledem na celé pohoří. V zimě a brzy na jaře bývá průsmyk zasněžený, ověřte si sjízdnost.', 43.0271, -4.7956, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumento%20al%20oso%20pardo%20en%20el%20Collado%20de%20Llesba.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monumento%20al%20oso%20pardo%20en%20el%20Collado%20de%20Llesba.jpg"}'::text[], 8);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Ronda (Puente Nuevo)', 'Ronda se pyšní ohromujícím mostem Puente Nuevo, který se klene 120 metrů nad soutěskou El Tajo. Zaparkuj motorku poblíž centra a projdi se k vyhlídce nad kaňonem, výhled stojí za to. Ideální startovní bod pro celý okruh bílých měst.', 36.74117, -5.16667, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Puente%20Nuevo,%20Ronda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ronda%20Spain%20Puente-Nuevo-de-Ronda-01.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Tragatá (Ronda)', 'Tragatá je stylová tapasová restaurace šéfkuchaře Benita Gómeze, vedená v průvodci Michelin a proslulá kreativním pojetím andaluské kuchyně. Skvělé hodnocení kolem 4,4 hvězdičky potvrzuje tisíce spokojených hostů. Ideální zastávka na oběd v centru Rondy před vyjížďkou za bílými vesnicemi.', 36.7429, -5.1672, 'https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/View%20of%20Puente%20Nuevo%20bridge%20in%20Ronda%20Spain.jpg"}'::text[], 1),
    (v_route, 'Setenil de las Bodegas', 'Setenil je proslulé domy zapuštěnými přímo pod převislé skalní stěny, ulice tu doslova mizí pod kamenem. Silnice sem z Rondy nabízí příjemné táhlé zatáčky mezi olivovými háji. Nech motorku na okraji obce, uličky jsou úzké a plné turistů.', 36.8622, -5.1787, 'https://commons.wikimedia.org/wiki/Special:FilePath/Setenil%20de%20las%20Bodegas%202019-10-23%2003.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Setenil%20de%20las%20Bodegas%202019-10-23%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Setenil-DSC09997.JPG"}'::text[], 2),
    (v_route, 'Zahara de la Sierra', 'Bílá vesnice Zahara se choulí pod maurskou věží nad tyrkysovou nádrží Embalse de Zahara-El Gastor. Silnice A-2300 a serpentiny průsmyku Puerto de las Palomas patří k nejkrásnějším úsekům celé trasy. Zastav na vyhlídce nad přehradou a vychutnej si panorama.', 36.8406, -5.3905, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andaluc%C3%ADa%20Zahara%20de%20la%20Sierra1%20tango7174.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Andaluc%C3%ADa%20Zahara%20de%20la%20Sierra1%20tango7174.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20pantano%20de%20Zahara%20de%20la%20Sierra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zahara%20de%20la%20Sierra,%20Spain.jpg"}'::text[], 3),
    (v_route, 'Grazalema', 'Grazalema leží v srdci stejnojmenného přírodního parku, jednoho z nejdeštivějších míst Španělska, díky čemuž je okolí nezvykle zelené. Klikaté horské silnice sem vedou hustými borovými lesy a nabízejí skvělou jízdu. Dobré místo na kávu a doplnění paliva před další etapou.', 36.75836, -5.36607, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Grazalema%20(C%C3%A1diz).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Grazalema%20(C%C3%A1diz).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Parque%20natural%20de%20la%20Sierra%20de%20Grazalema,%20Espa%C3%B1a,%20enero%20de%202011.JPG"}'::text[], 4),
    (v_route, 'Júzcar', 'Júzcar je celá modrá vesnice v údolí Genal, kterou natřeli kvůli premiéře filmu o Šmoulech a modrá už zůstala. Cesta sem z Rondy vede úzkou vyhlídkovou okreskou plnou kaštanů, technicky zábavná porce zatáček. Fotogenické zastavení mimo hlavní turistické trasy.', 36.62442, -5.16971, 'https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%BAzcar%20M%C3%A1laga%20Andalusia%20Spain%20smurf%20town.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%BAzcar%20M%C3%A1laga%20Andalusia%20Spain%20smurf%20town.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%BAzcar,%20Spain%20(%20The%20BLUE%20SMURF%20TOWN).JPG"}'::text[], 5),
    (v_route, 'El Chorro / Caminito del Rey', 'El Chorro ukrývá slavnou lávku Caminito del Rey přišpendlenou ke stěnám dramatické soutěsky nad řekou Guadalhorce. Silnice kolem přehrad sem nabízí úzké zatáčky a výhledy na tyrkysové nádrže. Pokud chceš projít stezku, rezervuj si vstupenku předem, kapacita je omezená.', 36.9068, -4.75923, 'https://commons.wikimedia.org/wiki/Special:FilePath/El%20famoso%20Caminito%20del%20Rey.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/El%20famoso%20Caminito%20del%20Rey.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Caminito%20del%20Rey%204.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Caminito%20del%20Rey%20Andalusia-13%20(25635110194).jpg"}'::text[], 6),
    (v_route, 'Granada (Alhambra)', 'Alhambra je maurský palácový komplex a klenot Granady, zapsaný na seznamu UNESCO. Přijeď brzy a zaparkuj na hlídaném parkovišti, centrum je pro motorky komplikované. Vstupenky si kup předem online, jinak se dovnitř nedostaneš.', 37.17604, -3.58828, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20la%20Alhambra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20la%20Alhambra.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/La%20Alhambra%20vista%20desde%20el%20Albaic%C3%ADn.%20Granada.JPG"}'::text[], 7),
    (v_route, 'Restaurace: Mirador de Morayma (Granada)', 'Mirador de Morayma je půvabná restaurace v maurské čtvrti Albaicín s terasovou zahradou a úchvatným výhledem přímo na Alhambru. Podává povýšenou andaluskou kuchyni s mozárabskými motivy a těší se skvělému hodnocení kolem 4,4 hvězdičky. Rezervuj si stůl s výhledem předem, jde o zážitkovou tečku za druhým dnem trasy.', 37.1795, -3.5906, 'https://commons.wikimedia.org/wiki/Special:FilePath/La%20Alhambra%20vista%20desde%20el%20Albaic%C3%ADn.%20Granada.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/La%20Alhambra%20vista%20desde%20el%20Albaic%C3%ADn.%20Granada.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20la%20Alhambra.jpg"}'::text[], 8),
    (v_route, 'Pico Veleta (silnice)', 'Silnice na Pico Veleta je nejvýše položená zpevněná vozovka v Evropě, stoupá až přes 3300 metrů nad mořem. Horní úsek za lyžařským střediskem je pro běžnou dopravu uzavřený, ale výjezd k závoře je nezapomenutelný zážitek s řídkým vzduchem a výhledy. Ober se teple, i v létě tu bývá chladno a počasí se rychle mění.', 37.0558, -3.3658, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pico%20del%20Veleta%20Sierra%20Nevada.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pico%20del%20Veleta%20Sierra%20Nevada.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Veleta-pico.JPG"}'::text[], 9);
  insert into public.routes
