  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Tallinn – staré město (Raekoja plats)', 'Středověké staré město Tallinnu zapsané na seznamu UNESCO je ideálním startem trasy. Radniční náměstí (Raekoja plats) lemují barevné hanzovní domy a gotická radnice. Motorku nechte za hradbami na parkovišti a jádro si projděte pěšky po dlažebních kostkách, které nejsou pro jízdu příjemné.', 59.4358, 24.7405, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(4).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(4).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(1).JPG"}'::text[], 0),
    (v_route, 'Restaurace: Rataskaevu 16 (Tallinn)', 'Rataskaevu 16 patří k nejoblíbenějším restauracím v tallinnském Starém Městě a je skvělým místem na oběd hned na startu trasy. Kuchyně staví na moderním pojetí estonské a severské klasiky s lokálními surovinami jako losí maso a černý chléb. S hodnocením kolem 4,8 hvězdy na Googlu i TripAdvisoru jde o jednu z nejlépe hodnocených restaurací ve městě, takže si stůl raději rezervujte předem.', 59.4372, 24.7423, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tallinna%20Raekoda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tallinna%20Raekoda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tallinn%20Raekoja%20plats%20(1).JPG"}'::text[], 1),
    (v_route, 'Palmse mõis (Lahemaa)', 'Barokní panské sídlo Palmse je srdcem národního parku Lahemaa a sídlí zde jeho návštěvnické centrum. Kolem zámečku najdete upravený park, rybníky a hospodářské budovy k procházce. Cesta sem vede klidnými lesními silnicemi mimo hlavní tahy, které si motorkář užije.', 59.51275, 25.95477, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palmse%20manor%20house%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palmse%20manor%20house%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/PalmseManorPark.jpg"}'::text[], 2),
    (v_route, 'Sagadi mõis (Lahemaa)', 'Růžové panské sídlo Sagadi s lesnickým muzeem leží kousek od Palmse a doplňuje prohlídku Lahemaa. Areál obklopuje symetrická zahrada a starý park se vzrostlými stromy. Mezi oběma sídly se dá krásně projet po úzkých venkovských cestách bez provozu.', 59.5167, 26.118, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sagadi%20manor%20house.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sagadi%20manor%20house.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sagadi%20manor,%20Parque%20Nacional%20Lahemaa,%20Estonia,%202012-08-12,%20DD%2017.JPG"}'::text[], 3),
    (v_route, 'Trajekt Virtsu–Kuivastu', 'Z přístavu Virtsu na pevnině přeplouvá trajekt úžinu Suur väin do Kuivastu na ostrově Muhu, odkud se po hrázi pokračuje na Saaremaa. Přeprava trvá zhruba 25–30 minut a motorky se nakládají mezi prvními. V hlavní sezóně si jízdenku raději rezervujte předem, ať nečekáte na další spoj.', 58.575, 23.51, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ferry%20Virtsu%20-%20Kuivastu,%20Estonia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ferry%20Virtsu%20-%20Kuivastu,%20Estonia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Virtsu-Kuivastu%20(Suur%20v%C3%A4in).jpg"}'::text[], 4),
    (v_route, 'Kaali – meteoritický kráter', 'Kaali je skupina meteoritických kráterů, jejichž hlavní jámu dnes vyplňuje kruhové jezírko obklopené valem. Vznikl dopadem meteoritu před tisíci lety a je jedním z nejznámějších přírodních úkazů Estonska. U kráteru je parkoviště i malé návštěvnické centrum, takže je to příjemná zastávka na svačinu.', 58.37279, 22.6694, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaali%20meteorite%20crater.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaali%20meteorite%20crater.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaali%20Meteorite%20Crater,%20Kaali,%20Saaremaa,%20Estonia%2003.jpg"}'::text[], 5),
    (v_route, 'Angla – větrné mlýny', 'Na kopečku u silnice mezi Upa a Leisi stojí pětice historických větrných mlýnů, symbol venkovského Saaremaa. Čtyři jsou typické ostrovní kozlíkové mlýny, jeden je holandského typu z roku 1927. U areálu je muzeum lidové kultury a kavárna, ideální fotostop přímo u trasy.', 58.549, 22.632, 'https://commons.wikimedia.org/wiki/Special:FilePath/Saaremaa%20Angla%20Windmills%20Farm%20-%20Angla%20Tedre%20Talu%20Tuuleveski%2020896.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Saaremaa%20Angla%20Windmills%20Farm%20-%20Angla%20Tedre%20Talu%20Tuuleveski%2020896.JPG"}'::text[], 6),
    (v_route, 'Panga pank – útes', 'Panga pank je nejvyšší pobřežní útes ostrovů Saaremaa a Muhu, tyčící se až 20 metrů nad moře. Vápencová stěna se táhne podél severního pobřeží a nabízí výhledy na moře i klidnou rekreační zónu. K okraji se dá dojet po klidné cestě, pozor ale na strmý sráz při procházce.', 58.56986, 22.29038, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panga%20pank.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panga%20pank.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panga%20pank%20-%20cliff%20in%20Saaremaa%20-%20panoramio.jpg"}'::text[], 7),
    (v_route, 'Kuressaare – biskupský hrad', 'Kuressaare v hlavním městě Saaremaa je jedním z nejlépe dochovaných středověkých hradů v Pobaltí, obklopený vodním příkopem a bastiony. Kamenná pevnost dnes ukrývá muzeum a je dominantou celého města. Kolem hradu je rozlehlý park a klidné centrum vhodné na přenocování mezi oběma dny.', 58.25382, 22.49217, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare-linnus,%202010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare-linnus,%202010.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare%20linnus%20%C3%B5hust.jpg"}'::text[], 8),
    (v_route, 'Restaurace: MO Restaurant (Kuressaare)', 'MO Restaurant je fine-dining restaurace u klubovny Saare Golf kousek od Kuressaare, ideální zastávka v polovině trasy před přenocováním. Kuchyně kombinuje starou evropskou klasiku s prvotřídními místními surovinami a k jídlu se pojí krásný výhled z prosklené jídelny i terasy. S hodnocením kolem 4,5 hvězdy patří k nejlépe hodnoceným podnikům na ostrově Saaremaa.', 58.2589, 22.5119, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare%20linnus%20%C3%B5htuh%C3%A4maruses.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kuressaare%20linnus%20%C3%B5htuh%C3%A4maruses.JPG"}'::text[], 9),
    (v_route, 'Sõrve – maják', 'Maják Sõrve stojí na samém jižním cípu poloostrova Sõrve a je nejjižnějším bodem Saaremaa. Cesta k němu po úzké kose mezi mořem po obou stranách patří k nejhezčím úsekům celé trasy. Za jasného počasí odsud dohlédnete až k lotyšskému pobřeží a je to symbolický cíl výletu.', 57.90982, 22.05537, 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B5rve%20tuletorn%202013.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B5rve%20tuletorn%202013.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%B5rve%20lighthouse%20on%20Saaremaa%20island.jpg"}'::text[], 10);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Železná Ruda', 'Živé horské městečko přímo u bavorské hranice je tradiční branou do západní Šumavy a startem celého okruhu. Dominuje mu barokní kostel Panny Marie Pomocné s neobvyklou cibulovou bání. Odtud vedou silnice k ledovcovým jezerům, na Špičák i k lanovce na Pancíř, takže je ideálním místem pro doplnění paliva a kávu před náročnou etapou.', 49.13743, 13.2352, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDelezn%C3%A1%20Ruda,%20Ostr%C3%BD,%20Svaroh,%20Jezern%C3%AD%20hora%20a%20%C5%A0pi%C4%8D%C3%A1k%20z%20pta%C4%8D%C3%ADho%20pohledu.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDelezn%C3%A1%20Ruda,%20Ostr%C3%BD,%20Svaroh,%20Jezern%C3%AD%20hora%20a%20%C5%A0pi%C4%8D%C3%A1k%20z%20pta%C4%8D%C3%ADho%20pohledu.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDelezn%C3%A1%20Ruda%20poh%C5%99ebi%C5%A1t%C4%9B%20Barab%C5%AF.JPG"}'::text[], 0),
    (v_route, 'Černé jezero', 'Největší a nejhlubší přírodní jezero v České republice leží v ledovcovém karu pod strmou stěnou Jezerní hory. Temná hladina o rozloze bezmála devatenácti hektarů se rozkládá v nadmořské výšce přes tisíc metrů a je obklopena hlubokými smrčinami. K jezeru se z parkoviště u Železné Rudy dochází po několika kilometrech pěšky, samotná cesta lesem je ale nezapomenutelná.', 49.17963, 13.18276, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A9%20jezero,%20%C5%A0umava%20(CZE).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A9%20jezero,%20%C5%A0umava%20(CZE).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C4%8Cern%C3%A9%20jezero,%20Svaroh,%20Ostr%C3%BD;%20vzadu%20Kaitersberg%20a%20Hoher%20Bogen%20z%20pta%C4%8D%C3%ADho%20pohledu.JPG"}'::text[], 1),
    (v_route, 'Prášily', 'Klidná horská obec na úpatí Ždánidel byla dlouhá desetiletí součástí uzavřeného vojenského prostoru, což jí zachovalo divokou přírodu bez masové zástavby. Připomínkou dramatické minulosti jsou zbytky kostela svatého Prokopa i zaniklá osada Hůrka. Prášily jsou dnes výchozím bodem k Prášilskému jezeru a na hřebeny při hranici s Bavorskem.', 49.10513, 13.37794, 'https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20Saint%20Procopius%20Pr%C3%A1%C5%A1ily%20001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Church%20of%20Saint%20Procopius%20Pr%C3%A1%C5%A1ily%20001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/U%20H%C5%AFrky%20%C5%A0umava.JPG"}'::text[], 2),
    (v_route, 'Srní', 'Rozlehlá horská obec nad údolím Vydry je významným rekreačním střediskem v samém srdci Národního parku Šumava. Střed obce se pyšní kostelem Nejsvětější Trojice a nedaleko se nachází návštěvnické centrum s výběhy vlků a rysů. Srní je pohodlnou křižovatkou cest k Modravě, Povydří i k hradlovému mostu na Vchynicko-tetovském kanálu.', 49.08806, 13.46639, 'https://commons.wikimedia.org/wiki/Special:FilePath/Srn%C3%AD,%20centrum%20obce.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Srn%C3%AD,%20centrum%20obce.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Srn%C3%AD,%20kostel%20Nejsv%C4%9Bt%C4%9Bj%C5%A1%C3%AD%20Trojice%20(2013-08-15).jpg"}'::text[], 3),
    (v_route, 'Modrava', 'Malebná osada na soutoku Modravského, Roklanského a Filipohuťského potoka patří k nejnavštěvovanějším místům centrální Šumavy. Leží ve výšce téměř tisíc metrů a je obklopena rozsáhlými slatěmi a bezzásahovými smrčinami. Odtud vyjíždějí cyklisté i turisté k Březníku, na Tříjezerní slať i podél řeky Vydry, a v obci najdete kvalitní zázemí i vlastní pivovar.', 49.02444, 13.49306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modrava%20-%20obecn%C3%AD%20%C3%BA%C5%99ad.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modrava%20-%20obecn%C3%AD%20%C3%BA%C5%99ad.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/National%20park%20%C5%A0umava%20(Czech%20Republic).jpg"}'::text[], 4),
    (v_route, 'Povydří (řeka Vydra)', 'Naučná stezka Povydří vede od bývalého královského dvorce Antýgl podél divoké řeky Vydry k Čeňkově pile a bývá označována za nejkrásnější úsek Šumavy. Řeka se prodírá obřím kamenným řečištěm plným balvanů, peřejí, tůní a obřích hrnců vymletých vodou. Motorku necháte na parkovišti a nejhezčí kus si projdete pěšky nad hučící vodou.', 49.08278, 13.42722, 'https://commons.wikimedia.org/wiki/Special:FilePath/River%20Vydra.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/River%20Vydra.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ant%C3%BDgl%20(%C5%A0umava)%201.JPG"}'::text[], 5),
    (v_route, 'Hrad Kašperk', 'Nejvýše položený královský hrad v Čechách nechal roku 1356 vystavět císař Karel IV. k ochraně zlatých dolů a Zlaté stezky. Zřícenina se dvěma mohutnými věžemi se tyčí na skalnatém hřbetu nad údolím Otavy severně od Kašperských Hor. Z ochozů se otevírá dechberoucí výhled na šumavské lesy a hřebeny, hrad je přístupný s průvodcem.', 49.16608, 13.55693, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Kasperk%20-%20vychodni%20vez%2058.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Kasperk%20-%20vychodni%20vez%2058.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%A1persk%C3%A9%20Hory,%20radnice.JPG"}'::text[], 6),
    (v_route, 'Restaurace: Nebespán (Kašperské Hory)', 'Restaurace a kavárna Nebespán přímo na náměstí v Kašperských Horách nabízí zážitkovou gastronomii, kde se snoubí francouzská technika s lokálními šumavskými surovinami. Podnik získal ocenění 13,5 bodu a dvě čepice od průvodce Gault-Millau a řadí se mezi čtyřicítku nejlepších restaurací v celé ČR. Ideální zastávka na oběd na konci první etapy okruhu.', 49.14264, 13.55611, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%A1persk%C3%A9%20Hory,%20radnice.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ka%C5%A1persk%C3%A9%20Hory,%20radnice.JPG"}'::text[], 7),
    (v_route, 'Vimperk', 'Historické město zvané brána Šumavy leží v údolí řeky Volyňky pod pralesem Boubín. Nad městem se tyčí rozsáhlý zámek, původně gotický hrad z poloviny 13. století, dnes se stálou expozicí a dělostřeleckou baštou Haselburg. Vimperk je proslulý knihtiskem a sklářstvím a je vhodným místem pro nocleh mezi první a druhou etapou.', 49.05459, 13.78174, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vimperk,%20z%C3%A1mek..JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vimperk,%20z%C3%A1mek..JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Vimperk%20-%20m%C4%9B%C5%A1%C5%A5ansk%C3%BD%20d%C5%AFm%20(U%20Jelena).jpg"}'::text[], 8),
    (v_route, 'Restaurace: Vodník (Vimperk)', 'Výletní restaurace Vodník na okraji Vimperka u stejnojmenného rybníka se specializuje na steaky a ryby z grilu a je nejlépe hodnoceným podnikem ve městě s hodnocením kolem 4,6 z 5. Prostředí u vody s terasou a příjemnou obsluhou je oblíbené u rodin i motorkářů. Skvělá volba pro vydatnou večeři před druhým dnem jízdy.', 49.05908, 13.76172, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vimperk%20-%20m%C4%9B%C5%A1%C5%A5ansk%C3%BD%20d%C5%AFm%20(U%20Jelena).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vimperk%20-%20m%C4%9B%C5%A1%C5%A5ansk%C3%BD%20d%C5%AFm%20(U%20Jelena).jpg"}'::text[], 9),
    (v_route, 'Kvilda', 'Kvilda je s nadmořskou výškou 1065 metrů nejvýše položenou obcí v České republice a jedním z nejchladnějších míst v zemi. Uprostřed obce stojí novogotický kostel svatého Štěpána a nedaleko pramení Teplá Vltava, zdrojnice nejdelší české řeky. Okolní pláně a slatě patří k nejmagičtějším scenériím celé Šumavy, zvláště za časných ranních mlh.', 49.0206, 13.5806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kvilda.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kvilda.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hodinovy%20Stroj%20Kostel%20Sv%20Stepana%20Kvilda%20D.jpg"}'::text[], 10),
    (v_route, 'Bučina', 'Bučina bývala nejvýše položenou osadou celé Šumavy ve výšce 1162 metrů, po odsunu německého obyvatelstva a v době železné opony však téměř zanikla. Dnes zde stojí novodobá kaple a odpočívadlo s nádhernými rozhledy přes Knížecí Pláně do nitra pohoří. Je to zároveň nejdeštivější místo Šumavy, kam vede jen úzká horská silnice od Kvildy.', 48.96622, 13.5922, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kvilda,%20Bu%C4%8Dina,%20v%C3%BDhled%20(2013-08-12;%2001).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kvilda,%20Bu%C4%8Dina,%20v%C3%BDhled%20(2013-08-12;%2001).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/2014-03-22%2013.06.56%20K%C5%99%C3%AD%C5%BE%20Bu%C4%8Dina.jpg"}'::text[], 11),
    (v_route, 'Boubínský prales', 'Národní přírodní rezervace Boubínský prales vyhlášená už v roce 1858 patří k nejstarším chráněným územím ve střední Evropě a chrání původní buko-smrkový porost pod vrcholem Boubína. Mohutné staleté stromy, tlející kmeny a naprosté ticho dělají z tohoto místa jeden z posledních skutečných pralesů. Výchozím bodem stezky kolem rezervace je romantické Boubínské jezírko.', 48.98167, 13.81833, 'https://commons.wikimedia.org/wiki/Special:FilePath/National%20nature%20reserve%20Boubinsky%20prales%20in%202011%20(23).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/National%20nature%20reserve%20Boubinsky%20prales%20in%202011%20(23).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/National%20nature%20reserve%20Boubinsky%20prales%20in%202011%20(19).JPG"}'::text[], 12),
    (v_route, 'Stezka korunami stromů Lipno', 'Nejjižnější bod okruhu leží nad Lipenskou přehradou u obce Lipno nad Vltavou. Stezka korunami stromů byla první svého druhu v České republice a nabízí procházku dřevěnou lávkou mezi větvemi až k vyhlídkové věži vysoké čtyřicet metrů. Z jejího vrcholu se otevírá panoráma celého Lipna i šumavských hřebenů a dolů se lze svézt jedním z nejdelších suchých tobogánů v zemi.', 48.65325, 14.23397, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stezka%20korunami%20strom%C5%AF%20Lipno%20(02).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stezka%20korunami%20strom%C5%AF%20Lipno%20(02).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stezka%20Korunami%20Stromu,%20Lipno%20nV.jpg"}'::text[], 13),
    (v_route, 'Churáňov / Zadov', 'Zadov s vrcholem Churáňov je nejznámějším lyžařským a běžeckým střediskem centrální Šumavy s desítkami kilometrů upravovaných tratí. Na Churáňově stojí meteorologická stanice a rozhledna na skokanském můstku, odkud je vidět daleko do kraje. Poslední zastávka okruhu před sjezdem serpentinami zpět k Železné Rudě nabízí i v létě pěkné výhledy a občerstvení.', 49.07304, 13.63256, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lanov%C3%A1%20dr%C3%A1ha%20Zadov-Chur%C3%A1%C5%88ov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lanov%C3%A1%20dr%C3%A1ha%20Zadov-Chur%C3%A1%C5%88ov.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ski-%C5%A0umava.JPG"}'::text[], 14);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Trosky', 'Zřícenina gotického hradu na dvou čedičových sopečných výběžcích je symbolem celého Českého ráje. Věže zvané Baba a Panna se tyčí do dálky a nabízejí jeden z nejikoničtějších pohledů v Čechách. Z ochozů je za jasného počasí vidět až do Krkonoš.', 50.5098, 15.2252, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trosky%20Castle%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trosky%20Castle%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Trosky%20Castle%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20Trosky.jpg"}'::text[], 0),
    (v_route, 'Hrubá Skála', 'Zámek postavený přímo na pískovcových skalách patří k nejromantičtějším místům Hruboskalska. Odtud vedou stezky mezi skalními věžemi k proslulým vyhlídkám nad údolím. Areál dnes slouží jako zámecký hotel s výhledy na skalní město.', 50.54507, 15.19436, 'https://commons.wikimedia.org/wiki/Special:FilePath/SchlossHrubaSkala.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/SchlossHrubaSkala.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hruba%20skala,%20z%C3%A1mek.jpg"}'::text[], 1),
    (v_route, 'Hrad Kost', 'Jeden z nejzachovalejších gotických hradů v Čechách stojí na pískovcovém ostrohu v romantickém údolí Plakánek. Mohutná bílá věž nad rybníkem dala vzniknout legendě o hradu, který byl ''tvrdý jako kost''. Údolí kolem je oblíbeným cílem pěších i motorkářů.', 50.49018, 15.13507, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Kost.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Kost.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Kost%20z%20Plak%C3%A1nku.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Kost%20-%20ctyri%20hrany%20veze.JPG"}'::text[], 2),
    (v_route, 'Prachovské skály', 'Nejznámější skalní město Českého ráje se soustavou úzkých roklí, vyhlídek a strmých pískovcových věží. Okruhy vedou kolem míst jako Císařská chodba či vyhlídka Českého ráje. Rezervace je rájem horolezců i turistů a leží jen pár kilometrů od Jičína.', 50.4681, 15.2853, 'https://commons.wikimedia.org/wiki/Special:FilePath/Czechia-Prachov-Rocks-944.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Czechia-Prachov-Rocks-944.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prachauer%20felsen%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Emperor''s%20Passage,%20Prachov%20Rocks.jpg"}'::text[], 3),
    (v_route, 'Hrad Valdštejn', 'Nejstarší hrad Českého ráje z 13. století stojí na skalních blocích spojených kamennými mosty se sochami. Barokní úpravy mu daly podobu romantického poutního místa s kaplí svatého Jana Nepomuckého. Z hradu je krásný výhled do okolí Turnova a na Hruboskalsko.', 50.56248, 15.16701, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20Vald%C5%A1tejn%2001(js).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20Vald%C5%A1tejn%2001(js).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Vald%C5%A1tejn1.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Kozlovna U Anděla (Jičín)', 'Oblíbená kozlovna přímo na Valdštejnově náměstí v historickém centru Jičína s vysokým hodnocením návštěvníků. Nabízí tradiční českou kuchyni připravenou moderním způsobem a čerstvě čepovaného Kozla. Ideální zastávka na začátku prvního dne před vyjížďkou do skalních měst.', 50.4366, 15.3515, 'https://commons.wikimedia.org/wiki/Special:FilePath/Domy%20%C4%8Dp.%2088%20-%2094%20Vald%C5%A1tejnovo%20n%C3%A1m%C4%9Bst%C3%AD,%20Ji%C4%8D%C3%ADn.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Domy%20%C4%8Dp.%2088%20-%2094%20Vald%C5%A1tejnovo%20n%C3%A1m%C4%9Bst%C3%AD,%20Ji%C4%8D%C3%ADn.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ji%C4%8D%C3%ADn%20-%20n%C3%A1m%C4%9Bst%C3%AD%2004.jpg"}'::text[], 5),
    (v_route, 'Vrchlabí', 'Brána do Krkonoš leží na řece Labi na úpatí nejvyšších českých hor. Dominantou města je renesanční zámek s nárožními věžemi a zámeckým parkem. Vrchlabí je centrem turistiky a zimních sportů a vhodným místem k občerstvení před cestou do hor.', 50.6266, 15.6094, 'https://commons.wikimedia.org/wiki/Special:FilePath/19890712070NR%20Vrchlab%C3%AD%20Schlo%C3%9F%20Hohenelbe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/19890712070NR%20Vrchlab%C3%AD%20Schlo%C3%9F%20Hohenelbe.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/19890712075NR%20Vrchlab%C3%AD%20Schlo%C3%9F%20Hohenelbe.jpg"}'::text[], 6),
    (v_route, 'Špindlerův Mlýn', 'Nejznámější horské středisko Krkonoš leží v údolí řeky Labe obklopené zalesněnými svahy. V létě je výchozím bodem pro treky k pramenům Labe a na hřebeny, v zimě lákadlem lyžařů. Serpentiny nad městem patří mezi nejkrásnější motorkářské úseky v Krkonoších.', 50.72611, 15.60917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spindlersmuehle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spindlersmuehle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0pindler%C5%AFv%20Ml%C3%BDn,%20n%C3%A1m%C4%9Bst%C3%AD,%20pohled%20p%C5%99es%20%C5%99eku.jpg"}'::text[], 7),
    (v_route, 'Restaurace: Orange le Moon (Špindlerův Mlýn)', 'Ceněná restaurace v areálu Hotelu Bedřiška v centru Špindlerova Mlýna nabízí moderní gastronomii i výběr bezmasých jídel. Hosté oceňují velké porce a příjemné prostředí, restaurace patří k nejlépe hodnoceným ve městě. Vhodná zastávka druhého dne před výstupem na Sněžku nebo po návratu z hor.', 50.72839, 15.59623, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spindlersmuehle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spindlersmuehle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0pindler%C5%AFv%20Ml%C3%BDn,%20n%C3%A1m%C4%9Bst%C3%AD,%20pohled%20p%C5%99es%20%C5%99eku.jpg"}'::text[], 8),
    (v_route, 'Sněžka (Pec pod Sněžkou)', 'Nejvyšší hora České republiky měří 1603 metrů a stojí na hranici s Polskem na hřebeni Krkonoš. Na vrchol se lze vydat pěšky nebo lanovkou z Pece pod Sněžkou a čeká zde poštovna i kaple svatého Vavřince. Za jasného počasí je z vrcholu panorama celých Sudet.', 50.7359, 15.7399, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nejvy%C5%A1%C5%A1%C3%AD%20vrchol%20Sn%C4%9B%C5%BEka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nejvy%C5%A1%C5%A1%C3%AD%20vrchol%20Sn%C4%9B%C5%BEka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sn%C4%9B%C5%BEka,%20nov%C3%A1%20po%C5%A1tovna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sniezka%20from%20krucze%20skaly.jpg"}'::text[], 9),
    (v_route, 'Harrachov – Mumlavský vodopád', 'Mumlavský vodopád na řece Mumlavě je asi deset metrů vysoký a mezi krkonošskými vodopády vyniká největším průtokem a šířkou vody. Leží zhruba kilometr nad Harrachovem a je snadno dostupný po značené stezce. Okolí láká k procházce a je oblíbeným zakončením horské části trasy.', 50.77065, 15.45323, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mumlavsk%C3%A9%20vodop%C3%A1dy.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mumlavsk%C3%A9%20vodop%C3%A1dy.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Harrachov,%20Mumlavsk%C3%BD%20vodop%C3%A1d%20(1).jpg"}'::text[], 10),
    (v_route, 'Jičín', 'Historické město Albrechta z Valdštejna a brána do Českého ráje s krásným Valdštejnovým náměstím. Dominantou je 52 metrů vysoká renesanční Valdická brána s vyhlídkovým ochozem. Jičín je také známý jako město pohádky Rumcajs a ideální výchozí bod celé trasy.', 50.4367, 15.3519, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ji%C4%8D%C3%ADn,%20Valdick%C3%A1%20br%C3%A1na%20-%20v%C4%9B%C5%BE%20(Vald%C5%A1tejnovo%20n%C3%A1m%C4%9Bst%C3%AD).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ji%C4%8D%C3%ADn,%20Valdick%C3%A1%20br%C3%A1na%20-%20v%C4%9B%C5%BE%20(Vald%C5%A1tejnovo%20n%C3%A1m%C4%9Bst%C3%AD).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ji%C4%8D%C3%ADn%20-%20n%C3%A1m%C4%9Bst%C3%AD%2004.jpg"}'::text[], 11);
  insert into public.routes
