  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pravčická brána', 'Největší přírodní skalní brána v Evropě a symbol Českého Švýcarska. Pískovcový oblouk o rozpětí 26,5 metru se klene ve výšce zhruba 16 metrů a nabízí strhující výhledy do okolní krajiny. Pod branou stojí romantický zámeček Sokolí hnízdo z 19. století s restaurací. Vstup na skalní ostroh je zpoplatněný a samotný oblouk je z důvodu ochrany nepřístupný.', 50.88396, 14.28142, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pravcicka_brana.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pravcicka_brana.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pravcicka_brana_2015-08_--3.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pravcicka_brana,pohled_zespoda.JPG"}'::text[], 0),
    (v_route, 'Hřensko – soutěsky Kamenice', 'Nejnižší místo Česka a brána do soutěsek řeky Kamenice. Edmundovou (Tichou) a Divokou soutěskou vás v hlubokém kaňonu provezou plavci na loďkách mezi kolmými pískovcovými stěnami. Vodní plavba je jedinečným zážitkem, na který se v sezoně stojí fronty. Obec Hřensko je zároveň ideálním startovním bodem pro výlety po celém národním parku.', 50.87444, 14.2425, 'https://commons.wikimedia.org/wiki/Special:FilePath/Canyon_of_Kamenice_River_(Kamenice_Gorge,_Edmundsklamm)_05.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Canyon_of_Kamenice_River_(Kamenice_Gorge,_Edmundsklamm)_05.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kamenice_River_01.jpg"}'::text[], 1),
    (v_route, 'Tisá – Tiské stěny', 'Rozsáhlé pískovcové skalní město tvořené bizarními věžemi, průchody a soutěskami, které dosahují výšky až 70 metrů. Značené okruhy Malými a Velkými Tiskými stěnami vedou úzkými skalními uličkami připomínajícími labyrint. Místo je vyhledávané turisty i horolezci a sloužilo jako filmová kulisa. Nachází se na západním okraji Labských pískovců u obce Tisá.', 50.78758, 14.02884, 'https://commons.wikimedia.org/wiki/Special:FilePath/20050626077DR_Tisá_(Tschechien)_Tyssaer_Wände.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/20050626077DR_Tisá_(Tschechien)_Tyssaer_Wände.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20050626017DR_Tisá_(Tschechien)_Tyssaer_Wände.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Tisa_4.JPG"}'::text[], 2),
    (v_route, 'Jetřichovice – Mariina vyhlídka', 'Skalní vyhlídka na vrcholu Mariiny skály nad obcí Jetřichovice s dřevěným altánem a jedním z nejkrásnějších rozhledů v celém Českém Švýcarsku. Z vyhlídky ve výšce 428 metrů se otevírá panorama Jetřichovických stěn, Vilemíniny stěny i vzdálených vrchů. Vyhlídka byla pojmenována po Marii Anně Kinské. K altánu vede pohodlná značená stezka z centra Jetřichovic.', 50.85528, 14.38139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mary''s_Rock_near_Jetřichovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mary''s_Rock_near_Jetřichovice.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vilemínina_stěna_z_Mariiny_vyhlídky.jpg"}'::text[], 3),
    (v_route, 'Děčín – zámek', 'Monumentální barokní zámek na pískovcové skále nad soutokem Labe a Ploučnice. K jeho nejznámějším částem patří Dlouhá jízda – impozantní zámecká přístupová cesta – a Růžová zahrada s gloriety. Zámek vlastnil po staletí rod Thun-Hohensteinů a dnes nabízí prohlídkové okruhy, výstavy a kulturní akce. Z teras jsou pěkné výhledy na město a řeku.', 50.7832, 14.2067, 'https://commons.wikimedia.org/wiki/Special:FilePath/Decin-castle-001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Decin-castle-001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zámek_Děčín_(by_Pudelek).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zámek_Děčín_IMG_1664.JPG"}'::text[], 4),
    (v_route, 'Restaurace: ARRIGŌ (Děčín)', 'Vyhlášená děčínská restaurace ARRIGŌ s hodnocením 4,6 na Googlu a doporučením v průvodci Michelin patří ke gastronomické špičce regionu. Nabízí moderní kuchyni s otevřeným výhledem do provozu a příjemnou komorní atmosféru. Je ideální zastávkou zhruba v polovině okruhu při průjezdu Děčínem. Fotografie zachycují město Děčín, kde se podnik nachází.', 50.7779, 14.1956, 'https://commons.wikimedia.org/wiki/Special:FilePath/Děčín_(Tetschen),_Czech_Republic.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Děčín_(Tetschen),_Czech_Republic.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Decin-castle-001.jpg"}'::text[], 5),
    (v_route, 'Panská skála (Kamenický Šenov)', 'Slavné čedičové varhany u Kamenického Šenova – dokonale pravidelné pětiboké až šestiboké kamenné sloupy vzniklé chladnutím lávy. Jde o nejstarší chráněný geologický útvar v Česku a jednu z nejfotografovanějších skalních zajímavostí. Sloupy se zrcadlí v malém jezírku pod skálou, což vytváří působivou scenérii. Místo je snadno dostupné a proslavil ho i film Pyšná princezna.', 50.76953, 14.48457, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panska_skala.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panska_skala.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Basalt-tschechien.jpg"}'::text[], 6),
    (v_route, 'Sloup v Čechách – skalní hrad', 'Unikátní skalní hrad vytesaný do osamělé 30 metrů vysoké pískovcové skály, přezdívaný česká Meteora. Původně středověké sídlo bylo v baroku přebudováno na poutní místo s poustevnou, skalním kostelem a křížovou cestou. Ochozy a chodby vytesané ve skále nabízejí pěkné výhledy do okolí Lužických hor. Hrad je přístupný v sezoně od dubna do října.', 50.72155, 14.5948, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skalní_hrad_Sloup_v_Čechách_04.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skalní_hrad_Sloup_v_Čechách_04.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Sloup_v_Čechách.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sloup,_skalní_hrad_-_ochoz7.jpg"}'::text[], 7),
    (v_route, 'Hrad Bezděz', 'Majestátní gotický hrad z 13. století založený Přemyslem Otakarem II. na výrazném čedičovém kopci ve výšce 604 metrů. Patří k nejlépe dochovaným raně gotickým hradům v Čechách a je nepřehlédnutelnou dominantou Máchova kraje. Byl zde vězněn mladý Václav II. a hrad opěvoval i básník Karel Hynek Mácha. Z hradních věží se otevírají daleké kruhové rozhledy.', 50.53694, 14.72083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bezděz_castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bezděz_castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad_Bezděz_(Bezděz)_5.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bezděz,_hrad,_2012_001.JPG"}'::text[], 8),
    (v_route, 'Luž (Lužické hory)', 'Nejvyšší hora Lužických i Žitavských hor s výškou 793 metrů, kuželovitý znělcový vrchol přímo na česko-německé hranici. Z vrcholové plošiny se za dobrého počasí otevírá dalekosáhlý výhled na Lužické hory, České Švýcarsko i saskou nížinu. Na vrchol vedou značené turistické stezky z Horní Světlé i z německé strany od Waltersdorfu. Dříve zde stávala výletní restaurace.', 50.85408, 14.66452, 'https://commons.wikimedia.org/wiki/Special:FilePath/Die_Lausche,_vom_Löbauer_Berg_aus_gesehen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Die_Lausche,_vom_Löbauer_Berg_aus_gesehen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/2011_Gipfelplateau_Lausche.JPG"}'::text[], 9);
