    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Praděd (vysílač a rozhledna)', 'Praděd je s 1491 m nejvyšší horou Moravy a Slezska a dominuje celému Hrubému Jeseníku. Na vrcholu stojí 146 m vysoký televizní vysílač, jehož prosklená plošina slouží jako rozhledna a je po Sněžce druhým nejvyšším místem republiky. Za jasného počasí odsud dohlédnete až na Beskydy, Praděd je proto vyhledávaným cílem motorkářů i turistů.', 50.08307, 17.23099, 'https://commons.wikimedia.org/wiki/Special:FilePath/Praded_TV_tower.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Praded_TV_tower.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Altvater_-_OT.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Prad%C4%9Bd%20(Altvater)%20-%20view%20from%20L%C3%A1zn%C4%9B%20Jesen%C3%ADk%20(Bad%20Gr%C3%A4fenberg).JPG"}'::text[], 0),
    (v_route, 'Červenohorské sedlo', 'Červenohorské sedlo v nadmořské výšce 1013 m je jedním z nejznámějších horských sedel Jeseníků a klíčovou křižovatkou silnice I/44 mezi Koutami nad Desnou a Jeseníkem. Serpentiny stoupající k sedlu patří mezi nejoblíbenější motorkářské úseky v kraji. V zimě je zde vyhledávané lyžařské středisko, v létě rozcestí dálkových turistických tras.', 50.10917, 17.16528, 'https://commons.wikimedia.org/wiki/Special:FilePath/CervenohorskeSedlo.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/CervenohorskeSedlo.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hruby%20Jesenik%20-%20Jeseniky,%20Czech%20Republic%2024.jpg"}'::text[], 1),
    (v_route, 'Karlova Studánka (lázně)', 'Karlova Studánka je půvabná lázeňská obec z konce 18. století, celá vystavěná z dřevěných empírových staveb a rozložená v údolí Bílé Opavy pod Pradědem. Chlubí se nejčistším ovzduším ve střední Evropě a léčí především dýchací a oběhové potíže. Kolonáda, pítka minerálních pramenů a hudební pavilon zvou k příjemné zastávce.', 50.07348, 17.30605, 'https://commons.wikimedia.org/wiki/Special:FilePath/%22Pitn%C3%BD%20pavilon%22%20(Karlova%20Stud%C3%A1nka).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%22Pitn%C3%BD%20pavilon%22%20(Karlova%20Stud%C3%A1nka).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Karlova%20Stud%C3%A1nka-Bad%20Karlsbrunn2.JPG"}'::text[], 2),
    (v_route, 'Rejvíz (rašeliniště)', 'Rejvíz je nejvýše položená horská osada Jeseníků a proslulá národní přírodní rezervace s rozsáhlým vrchovištním rašeliništěm. Po dřevěném chodníku dojdete až k tajemnému Velkému mechovému jezírku, obklopenému borovicí blatkou a masožravou rosnatkou. Naučná stezka nabízí ojedinělý pohled do světa vzácné rašelinné přírody.', 50.26318, 17.39529, 'https://commons.wikimedia.org/wiki/Special:FilePath/NPR%20Rejv%C3%ADz,%20Velk%C3%A9%20mechov%C3%A9%20jez%C3%ADrko%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/NPR%20Rejv%C3%ADz,%20Velk%C3%A9%20mechov%C3%A9%20jez%C3%ADrko%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozc.%20Mechovo%20Jez..JPG"}'::text[], 3),
    (v_route, 'Ramzová / Šerák', 'Ramzová je nejvýše položené železniční sedlo v Česku a nástupní místo dvouúsekové lanovky vedoucí až na vrchol Šeráku (1351 m). Z hřebene Šerák–Keprník se otevírají daleké výhledy a na temeni stojí historická Jiřího chata. Oblast je vyhlášená čistou horskou přírodou a je vstupní branou do stejnojmenné národní přírodní rezervace.', 50.19185, 17.06767, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0er%C3%A1k-Keprn%C3%ADk,%20Jesen%C3%ADky%20(10).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0er%C3%A1k-Keprn%C3%ADk,%20Jesen%C3%ADky%20(10).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hruby%20Jesenik%20-%20Jeseniky,%20Czech%20Republic%2024.jpg"}'::text[], 4),
    (v_route, 'Velké Losiny (zámek a papírna)', 'Velké Losiny proslavil renesanční zámek s trojpodlažními arkádami, nechvalně známý z čarodějnických procesů 17. století zachycených ve filmu Kladivo na čarodějnice. Hned nedaleko funguje od 16. století ruční papírna, jedna z nejstarších dochovaných v Evropě, kde se dodnes čerpá papír klasickou metodou. Obec doplňují sirné termální lázně a klidná parková zákoutí.', 50.019, 17.034, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Velk%C3%A9%20Losiny,%20Velk%C3%A9%20Losiny%20268.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Velk%C3%A9%20Losiny,%20Velk%C3%A9%20Losiny%20268.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Schloss-Velke-Losiny-9.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pap%C3%ADrna,%20V.%20Losiny.JPG"}'::text[], 5),
    (v_route, 'Dlouhé Stráně (přečerpávací elektrárna)', 'Přečerpávací vodní elektrárna Dlouhé Stráně je největší svého druhu v Česku a bývá řazena mezi divy republiky. Horní nádrž leží v nadmořské výšce 1350 m na vrcholu hory Dlouhé stráně a je nejvýše položenou vodní plochou v zemi. Elektrárna s výkonem 650 MW je částečně ukryta v podzemí a exkurze k horní nádrži nabízí velkolepé panorama Jeseníků.', 50.07126, 17.15676, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dlouhe%20strane%20horni%20nadrz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dlouhe%20strane%20horni%20nadrz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/P%C5%99e%C4%8Derp%C3%A1vac%C3%AD%20vodn%C3%AD%20elektr%C3%A1rna%20Dlouh%C3%A9%20Str%C3%A1n%C4%9B.%20Horn%C3%AD%20n%C3%A1dr%C5%BE.jpg"}'::text[], 6),
    (v_route, 'Bruntál (zámek)', 'Bruntál patří k nejstarším městům Česka, jeho městská práva sahají už do roku 1213. Renesančně přestavěný státní zámek na Zámeckém náměstí s válcovou věží a arkádovým nádvořím ukrývá cenné sbírky obrazů, zbraní a nábytku. Zámek obklopuje anglický park a je ideální zastávkou při návratu do centrální části okruhu.', 49.99038, 17.46466, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20-%20Brunt%C3%A1l.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20-%20Brunt%C3%A1l.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Brunt%C3%A1l.jpg"}'::text[], 7),
    (v_route, 'Videlský kříž', 'Videlský kříž je historické turistické rozcestí ve Videlském sedle mezi Karlovou Studánkou a Jeseníkem, poblíž horské osady Vidly. Odedávna sloužilo jako důležitá orientační křižovatka cest směřujících k Pradědu a Šerák–Keprnickému hřebeni. Dnes je klidným startovním bodem řady výletů do nitra Jeseníků.', 50.11694, 17.24361, 'https://commons.wikimedia.org/wiki/Special:FilePath/VidelskyKriz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/VidelskyKriz.jpg"}'::text[], 8),
    (v_route, 'Restaurace: Bistro Hubertus (Karlova Studánka)', 'Bistro Hubertus v srdci lázeňské Karlovy Studánky patří k nejlépe hodnoceným podnikům v okolí a je ideální zastávkou zhruba v polovině prvního dne okruhu. Nabízí čerstvou, chutně připravenou tradiční českou kuchyni v útulném a čistém prostředí. Oceňovaná je i příjemná obsluha a klidná atmosféra uprostřed horské přírody.', 50.07289, 17.30641, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karlova%20Stud%C3%A1nka-Bad%20Karlsbrunn2.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karlova%20Stud%C3%A1nka-Bad%20Karlsbrunn2.JPG"}'::text[], 9),
    (v_route, 'Restaurace: Radegastovna Bruntál (Bruntál)', 'Radegastovna Bruntál na náměstí Míru je vysoko hodnocená restaurace vhodná jako zastávka ve druhé polovině okruhu. Sází na poctivou, vždy čerstvou kuchyni, výborně ošetřený čepovaný Radegast a atmosféru klasické radegastovny. Kromě tradičních jídel zaujmou hosté i domácí burgery a pizzu.', 49.98829, 17.46441, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20-%20Brunt%C3%A1l.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20-%20Brunt%C3%A1l.JPG"}'::text[], 10);
