  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Rožnov pod Radhoštěm (Valašské muzeum v přírodě)', 'Nejstarší a největší skanzen ve střední Evropě, který od roku 1925 přibližuje tradiční život a architekturu Valašska. Dřevěné městečko, Valašská dědina a Mlýnská dolina ukrývají desítky původních roubených staveb přenesených z celého regionu. Rožnov je ideálním výchozím bodem celého okruhu a skvělým místem pro první zastavení na kávu.', 49.46136, 18.14919, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20-%20skanzen%20(Ro%C5%BEnov%20pod%20Radho%C5%A1t%C4%9Bm)%20-%20D%C5%99ev%C4%9Bn%C3%A9%20m%C4%9Bste%C4%8Dko%20021.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20-%20skanzen%20(Ro%C5%BEnov%20pod%20Radho%C5%A1t%C4%9Bm)%20-%20D%C5%99ev%C4%9Bn%C3%A9%20m%C4%9Bste%C4%8Dko%20021.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20-%20skanzen%20(Ro%C5%BEnov%20pod%20Radho%C5%A1t%C4%9Bm)%20-%20D%C5%99ev%C4%9Bn%C3%A9%20m%C4%9Bste%C4%8Dko%20018.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Muzeum%20-%20skanzen%20(Ro%C5%BEnov%20pod%20Radho%C5%A1t%C4%9Bm).JPG"}'::text[], 0),
    (v_route, 'Pustevny', 'Horské sedlo ve výšce 1018 metrů proslulé secesními stavbami Libušín a Maměnka od architekta Dušana Jurkoviče. Tyto pohádkové dřevěné útulny z konce 19. století patří k nejkrásnějším ukázkám lidové secese u nás. Pustevny jsou oblíbeným výchozím bodem k Radhošti a nabízejí panoramatické výhledy do celých Beskyd.', 49.4895, 18.265, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jin%C3%A1%20turistick%C3%A1%20stavba%20-%20are%C3%A1l%20Pustevny%20-%20Libu%C5%A1%C3%ADn%20a%20Mam%C4%9Bnka05.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jin%C3%A1%20turistick%C3%A1%20stavba%20-%20are%C3%A1l%20Pustevny%20-%20Libu%C5%A1%C3%ADn%20a%20Mam%C4%9Bnka05.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pustevny%202009-06%20(8).JPG"}'::text[], 1),
    (v_route, 'Radhošť (socha Radegasta)', 'Ikonická socha pohanského boha Radegasta stojí na hřebeni Radhoště ve výšce přes 1100 metrů. Původní dílo vytvořil v roce 1931 rodák Albín Polášek a dnes zde stojí žulová kopie. Mohutná socha slovanského boha slunce a hojnosti je jedním z nejfotografovanějších symbolů celých Beskyd.', 49.48222, 18.25417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Radegast%20-%20socha%20z%20Radho%C5%A1t%C4%9B.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Radegast%20-%20socha%20z%20Radho%C5%A1t%C4%9B.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Radegast-detail.JPG"}'::text[], 2),
    (v_route, 'Bumbálka', 'Horské sedlo v nadmořské výšce kolem 850 metrů na česko-slovenské hranici, kudy prochází hlavní hřeben Beskyd. Bývalý hraniční přechod je dnes křižovatkou turistických tras a oblíbeným cílem motorkářů díky klikaté silnici od Rožnova. V zimě se zde nachází lyžařský areál a udržované běžecké tratě.', 49.3833, 18.4, 'https://commons.wikimedia.org/wiki/Special:FilePath/B%C3%ADl%C3%A1%2C%20Bumb%C3%A1lka%20(2016-07-05%3B%2001).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/B%C3%ADl%C3%A1%2C%20Bumb%C3%A1lka%20(2016-07-05%3B%2001).jpg"}'::text[], 3),
    (v_route, 'Velké Karlovice (kostel Panny Marie Sněžné)', 'Roubený barokní kostel Panny Marie Sněžné z roku 1754 s unikátním půdorysem řeckého kříže patří k nejcennějším dřevěným stavbám na Valašsku. Založil jej hrabě František ze Žerotína a celý je pokrytý šindelem. Velké Karlovice jsou rozlehlou horskou obcí, která je dokonalým místem pro nocleh mezi prvním a druhým dnem okruhu.', 49.35936, 18.28558, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20Panny%20Marie%20Sn%C4%9B%C5%BEn%C3%A9%20(Velk%C3%A9%20Karlovice).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20Panny%20Marie%20Sn%C4%9B%C5%BEn%C3%A9%20(Velk%C3%A9%20Karlovice).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20Panny%20Marie%20Sn%C4%9B%C5%BEn%C3%A9%20Velk%C3%A9%20Karlovice.jpg"}'::text[], 4),
    (v_route, 'Soláň', 'Malebný vrch (861 m) na rozhraní Moravskoslezských Beskyd a Javorníků, odedávna považovaný za jedno z nejkrásnějších míst Valašska. Z hřebene se otevírají výhledy na všechny světové strany, od Radhoště až po Javorníky. Dřevěná Zvonice Soláň z roku 2006 slouží jako informační centrum a galerie a je oblíbeným cílem malířů i motorkářů.', 49.38983, 18.24341, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beskydy%2C%20Kamenn%C3%A1%20chata.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beskydy%2C%20Kamenn%C3%A1%20chata.JPG"}'::text[], 5),
    (v_route, 'Svatý Hostýn (bazilika Nanebevzetí Panny Marie)', 'Nejnavštěvovanější poutní místo Moravy s pozdně barokní bazilikou Nanebevzetí Panny Marie dokončenou v roce 1748. Dvouvěžový chrám na vrcholu Hostýna je od roku 2018 národní kulturní památkou a láká poutníky již po staletí. K areálu patří křížová cesta, rozhledna a nádherné výhledy do Hostýnských vrchů.', 49.37674, 17.70034, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%2C%20sv.%20Host%C3%BDn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%2C%20sv.%20Host%C3%BDn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Poutn%C3%AD%20m%C3%ADsto%20Svat%C3%BD%20Host%C3%BDn.jpg"}'::text[], 6),
    (v_route, 'Štramberk (Trúba)', 'Čtyřicet metrů vysoká gotická věž Trúba je posledním pozůstatkem středověkého hradu a od roku 1903 slouží jako rozhledna nad malebným městečkem Štramberk. Historické jádro s roubenými domky bývá přezdíváno Moravský Betlém a je městskou památkovou rezervací. Z ochozu věže se otevírá kruhový výhled na celé Beskydy - odměna za výstup po točitém schodišti.', 49.59238, 18.11629, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Tr%C3%BAba%20(%C5%A0tramberk).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Tr%C3%BAba%20(%C5%A0tramberk).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Stramberk%20Czech%20Republic%2001.JPG"}'::text[], 7),
    (v_route, 'Lysá hora', 'Nejvyšší vrchol Moravskoslezských Beskyd (1324 m) s charakteristickým televizním vysílačem a meteorologickou stanicí. Holý vrchol je významnou křižovatkou turistických tras a nabízí za dobré viditelnosti výhledy až na Tatry. Na vrchol vede od Krásné asfaltová silnice, takže je Lysá hora vděčným zakončením celého beskydského okruhu.', 49.5458, 18.4475, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lys%C3%A1%20hora%20v%20Beskydech%2C%20vrchol%20(3).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lys%C3%A1%20hora%20v%20Beskydech%2C%20vrchol%20(3).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lysa%20hora%2C%20beskydy%2C%20beskidy.jpg"}'::text[], 8),
    (v_route, 'Restaurace: Villa Rosenaw (Rožnov pod Radhoštěm)', 'Vyhlášená restaurace v secesní vile v centru Rožnova pod Radhoštěm s vysokým hodnocením hostů. Kuchyně staví na sezonních surovinách a kombinuje regionální i světové pokrmy - doporučujeme hovězí vývar, rizoto i čokoládový fondant. Ideální zastávka na začátku nebo konci prvního dne okruhu.', 49.4585, 18.1462, 'https://commons.wikimedia.org/wiki/Special:FilePath/Roznov%20p%20Radhostem01.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Roznov%20p%20Radhostem01.JPG"}'::text[], 9),
    (v_route, 'Restaurace: Valašská hospůdka Horal (Velké Karlovice)', 'Útulná valašská hospůdka ve Velkých Karlovicích s poctivou regionální gastronomií a moderním pojetím tradičních moravských jídel. Kromě klasiky nabízí i méně obvyklou zvěřinu a jehněčí, k tomu pečlivě čepované pivo oceněné Hvězdou sládků. Skvělé místo pro nocleh a večeři mezi prvním a druhým dnem cesty.', 49.3613, 18.315, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20Panny%20Marie%20Sn%C4%9B%C5%BEn%C3%A9%20Velk%C3%A9%20Karlovice.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kostel%20Panny%20Marie%20Sn%C4%9B%C5%BEn%C3%A9%20Velk%C3%A9%20Karlovice.jpg"}'::text[], 10);
  insert into public.routes
