  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Mikulov (zámek a Svatý kopeček)', 'Zámek Mikulov se tyčí nad malebným historickým městem na úpatí Pálavy a po staletí patřil rodu Dietrichsteinů. Nad městem se zvedá vápencový Svatý kopeček s poutní kaplí svatého Šebestiána a křížovou cestou, odkud je nádherný výhled na Mikulov a okolní vinice. Město je proslulé vinařstvím a bohatou židovskou historií. Ideální start i cíl celého okruhu.', 48.807, 16.636, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mikulov,%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mikulov,%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Overview%20of%20Mikulov%20from%20Svat%C3%BD%20Kope%C4%8Dek%202020%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mikulov%20N%C3%A1m%C4%9Bst%C3%AD%20shora.jpg"}'::text[], 0),
    (v_route, 'Pálava – Dívčí hrady (Děvičky)', 'Zřícenina gotického hradu Dívčí hrady, lidově zvaného Děvičky, je nejznámější dominantou Pavlovských vrchů. Hrad na vápencovém hřebeni ve výšce 428 metrů byl poprvně zmíněn už roku 1222 a za třicetileté války jej vypálili Švédové. Od zbytků věží se otevírá jeden z nejkrásnějších rozhledů na Novomlýnské nádrže a celou Pálavu. K ruinám vede pohodlná naučná stezka.', 48.86944, 16.64972, 'https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%ADv%C4%8D%C3%AD%20Hrady.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/D%C3%ADv%C4%8D%C3%AD%20Hrady.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zbytky%20v%C4%9B%C5%BEe,%20D%C3%ADv%C4%8D%C3%AD%20Hrady,%20Pavlov.JPG"}'::text[], 1),
    (v_route, 'Pavlov', 'Vinařská obec Pavlov leží na úpatí nejvyššího vrcholu Pálavy Děvína přímo nad Novomlýnskými nádržemi. Malebné náměstíčko lemují stavení lidové architektury a proslulé vinné sklepy zapsané mezi kulturní památky. Už v 15. století byl Pavlov největší vinařskou obcí mikulovského panství. Dnes je vyhledávaným cílem milovníků vína, výhledů a klidné atmosféry pod skalami.', 48.8733, 16.6706, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pavlov.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pavlov.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pavlov''s%20House.jpg"}'::text[], 2),
    (v_route, 'Novomlýnské nádrže (Pálava)', 'Kaskáda tří přehradních nádrží na řece Dyji pod Pavlovskými vrchy patří k nejfotogeničtějším místům jižní Moravy. Hladina se zrcadlí pod siluetou Pálavy a Děviček a nabízí ráj pro ptactvo, rybáře i cyklisty. Střední Věstonická nádrž je přírodní rezervací s hnízdními ostrovy. Zastavte se u hráze na výhled na vodu a hory.', 48.8891, 16.6086, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20Ml%C3%BDny%20Reservoir%20-%20Dam%202020%2003.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A9%20Ml%C3%BDny%20Reservoir%20-%20Dam%202020%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vestonicka%20nadrz.jpg"}'::text[], 3),
    (v_route, 'Lednice (zámek a minaret)', 'Novogotický zámek Lednice patří k nejnavštěvovanějším památkám Česka a je srdcem Lednicko-valtického areálu zapsaného na seznam UNESCO. V rozlehlém krajinářském parku stojí unikátní téměř šedesátimetrový Minaret, orientální rozhledna s vyhlídkou do celého areálu. Park protkaný kanály a romantickými stavbami zve k procházce i projížďce loďkou. Nezapomenutelné spojení architektury a přírody.', 48.79995, 16.80388, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lednice%20(Eisgrub)%20-%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lednice%20(Eisgrub)%20-%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Minaret%20in%20Lednice%20-%20pres%20vodu.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Minaret%20in%20Lednice%20-%20z%20parku.JPG"}'::text[], 4),
    (v_route, 'Valtice (zámek)', 'Barokní zámek Valtice býval hlavním sídlem knížecího rodu Lichtenštejnů a je považován za jednu z nejkrásnějších barokních rezidencí střední Evropy. Reprezentativní sály, kaple a rozlehlý park tvoří protipól k romantické Lednici na druhém konci areálu. Ve sklepení sídlí Národní vinařské centrum a Salon vín České republiky. Valtice jsou právem nazývány hlavním městem vína.', 48.73921, 16.75527, 'https://commons.wikimedia.org/wiki/Special:FilePath/Valtice%20z%C3%A1mek.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Valtice%20z%C3%A1mek.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Valtice%20zamek.jpg"}'::text[], 5),
    (v_route, 'Znojmo (rotunda a podzemí)', 'Znojmo je starobylé vinařské město nad kaňonem řeky Dyje s bohatou historií. Románská rotunda svaté Kateřiny ukrývá unikátní nástěnné malby z 11. a 12. století zachycující přemyslovské knížata. Pod městem se rozkládá rozsáhlé Znojemské podzemí – kilometry chodeb a sklepů vytesaných do skály. Prohlídka spojuje středověké tajemno s moravským vínem.', 48.85543, 16.04348, 'https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo%20(Znaim)%20-%20Rotunda%20svat%C3%A9%20Kate%C5%99iny.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo%20(Znaim)%20-%20Rotunda%20svat%C3%A9%20Kate%C5%99iny.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo-The%20Underground%20Passages%201.jpg"}'::text[], 6),
    (v_route, 'Šatov (Malovaný sklep)', 'Malovaný sklep v Šatově je jedinečnou technickou i uměleckou památkou znojemského vinařství. Jeho stěny pokrývají barevné reliéfní malby, které místní samouk Maxmilián Appeltauer vytvářel s láskou celých 33 let svého života. Výjevy z pohádek, historie i každodenního života zdobí chodby ražené do sprašové půdy. Šatov leží v srdci znojemské vinařské podoblasti u hranic s Rakouskem.', 48.796, 16.01, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov,%20Malovan%C3%BD%20sklep.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov,%20Malovan%C3%BD%20sklep.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%A0atov,%20star%C3%A1%20radnice%2003.JPG"}'::text[], 7),
    (v_route, 'Restaurace: Hospůdka Maxwilliam (Znojmo)', 'Stylová hospůdka v historickém centru Znojma nedaleko rotundy má na Google hodnocení kolem 4,6 hvězdičky a je oblíbeným cílem gurmánů. Specialitou jsou denně připravovaná pečená a vařená kolena, žebra a další masové speciality, které skvěle padnou po prohlídce podzemí. K jídlu si dáte místní znojemské víno nebo pivo v přátelské atmosféře. Ideální zastávka zhruba v polovině dvoudenního okruhu.', 48.85447, 16.04868, 'https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo,%20n%C3%A1m%C4%9Bst%C3%AD%20Svobody.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Znojmo,%20n%C3%A1m%C4%9Bst%C3%AD%20Svobody.jpg"}'::text[], 8);
