  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Punkevní jeskyně a propast Macocha', 'Nejznámější zpřístupněná jeskyně Moravského krasu s podzemní plavbou na loďkách po říčce Punkvě. Prohlídka vrcholí na dně propasti Macocha, hluboké přes 138 metrů, kterou shlédnete i shora ze dvou vyhlídkových můstků. Na horní okraj propasti se svezete lanovkou a cestou minete Masarykův dóm plný krápníkové výzdoby. Vstup je časově omezený, proto si rezervujte lístky předem.', 49.37083, 16.72611, 'https://commons.wikimedia.org/wiki/Special:FilePath/Propast%20Macocha.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Propast%20Macocha.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Punkevn%C3%AD%20jeskyn%C4%9B%20-%20Masaryk%C5%AFv%20d%C3%B3m%20(by%20Pudelek).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Punkva%20lodicky.JPG"}'::text[], 0),
    (v_route, 'Sloupsko-šošůvské jeskyně', 'Rozsáhlý labyrint dómů, chodeb a propastí v severní části Moravského krasu, patřící k nejdelším zpřístupněným jeskyním u nás. Uvidíte bohatou krápníkovou výzdobu, hluboké propasti i doklady pravěkého osídlení z jeskyně Kůlna. Na výběr jsou kratší i delší okruh, ten delší vede až do spodních pater. Klidná zastávka jen pár kilometrů od Macochy, ideální na doplnění prvního dne.', 49.41111, 16.73806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vstup%20do%20jesky%C5%88%C3%AD,%20p%C5%99%C3%ADrodn%C3%AD%20rezervace%20Sloup%C5%A1ko-%C5%A0o%C5%A1%C5%AFvsk%C3%A9%20jeskyn%C4%9B,%20okres%20Blansko.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vstup%20do%20jesky%C5%88%C3%AD,%20p%C5%99%C3%ADrodn%C3%AD%20rezervace%20Sloup%C5%A1ko-%C5%A0o%C5%A1%C5%AFvsk%C3%A9%20jeskyn%C4%9B,%20okres%20Blansko.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sloupsko-%C5%A1o%C5%A1%C5%AFvsk%C3%A9-jeskyn%C4%9B-interi%C3%A9r2018plakety.jpg"}'::text[], 1),
    (v_route, 'Arcibiskupský zámek a zahrady Kroměříž (UNESCO)', 'Honosné arcibiskupské sídlo s bohatými interiéry, obrazárnou a věží s výhledem na město patří spolu se zahradami od roku 1998 na Seznam světového dědictví UNESCO. Barokní Květná zahrada uchvátí přísnou geometrií, dlouhou kolonádou a rotundou, zatímco Podzámecká zahrada láká k procházce v anglickém parku se vzácnými stromy. Zámek je přirozeným místem pro nocleh a rozdělení trasy na dva dny. Ráno odsud vyrazíte na jih do srdce Slovácka.', 49.30041, 17.39353, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kv%C4%9Btn%C3%A1%20zahrada%20v%20Krom%C4%9B%C5%99%C3%AD%C5%BEi.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kv%C4%9Btn%C3%A1%20zahrada%20v%20Krom%C4%9B%C5%99%C3%AD%C5%BEi.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Park%20Kv%C4%9Btn%C3%A1%20zahrada%20(Krom%C4%9B%C5%99%C3%AD%C5%BE),%20Gen.%20Svobody,%20Krom%C4%9B%C5%99%C3%AD%C5%BE%2013.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kromeriz%20Kvetna%20zahrada%20Kralici%20kopec%20socha.jpg"}'::text[], 2),
    (v_route, 'Zámek Buchlovice', 'Elegantní barokní zámek postavený na počátku 18. století v italském stylu jako letní šlechtické sídlo. Prohlídkové okruhy ukazují zařízené interiéry, sbírky a atmosféru panského života, venku pak zaujme rozlehlý anglický park s exotickými dřevinami a fuchsiemi. Zámek leží přímo v obci Buchlovice na úpatí Chřibů, jen kousek od hradu Buchlov. Ideální první zastávka druhého dne.', 49.08402, 17.33651, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Buchlovice.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Buchlovice.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Buchlovice%20-%20hlavn%C3%AD%20budova.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek%20Buchlovice%20-%20ka%C5%A1na.JPG"}'::text[], 3),
    (v_route, 'Hrad Buchlov', 'Mohutný královský hrad ze 13. století stojí na zalesněném vrcholu Chřibů a patří k nejlépe dochovaným hradům na Moravě. Z hradních věží se otevírá dechberoucí výhled na Slovácko, Bílé Karpaty i vzdálené Chřiby. Prohlídky přibližují gotické i renesanční sály, hradní kuchyni a sbírky. K hradu vede od parkoviště krátký, ale svižný výstup lesem.', 49.10745, 17.31192, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Buchlov%20(Chrast%C4%9B).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Buchlov%20(Chrast%C4%9B).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Buchlov%20-%20vstupn%C3%AD%20br%C3%A1na.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Buchlov%20-%20interi%C3%A9r.JPG"}'::text[], 4),
    (v_route, 'Velehrad – bazilika Nanebevzetí Panny Marie a sv. Cyrila a Metoděje', 'Nejvýznamnější poutní místo Moravy a duchovní srdce cyrilometodějské tradice. Monumentální barokní bazilika s bohatě zdobeným interiérem a hlavním oltářem je cílem tisíců poutníků, zvláště při Národní pouti v červenci. Areál bývalého cisterciáckého kláštera dýchá klidem a historií sahající do 13. století. Zastávka vhodná i pro nevěřící díky výjimečné architektuře.', 49.10349, 17.39587, 'https://commons.wikimedia.org/wiki/Special:FilePath/Velehrad%20-%20bazilika.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Velehrad%20-%20bazilika.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velehrad%20-%20Basilica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Velehrad,%20bazilika,%20interi%C3%A9r,%20hlavn%C3%AD%20olt%C3%A1%C5%99.JPG"}'::text[], 5),
    (v_route, 'Baťův kanál – přístav Spytihněv', 'Přístav na historické vodní cestě, kterou nechal ve 30. letech vybudovat Baťa k dopravě lignitu, dnes slouží rekreační plavbě. Ze Spytihněvi můžete vyrazit na výletní loď nebo si půjčit malé plavidlo bez kapitánského průkazu a proplout jednou z plavebních komor. Nábřeží nad plavební komorou je bezbariérové a příjemné k procházce. Osvěžující zastávka mezi památkami druhého dne.', 49.15556, 17.48333, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C5%A5%C5%AFv%20kan%C3%A1l%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C5%A5%C5%AFv%20kan%C3%A1l%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Spytihn%C4%9Bv,%20Rejda.jpg"}'::text[], 6),
    (v_route, 'Skanzen Strážnice – Muzeum vesnice jihovýchodní Moravy', 'Rozlehlý skanzen na okraji Strážnice představuje lidovou architekturu Slovácka a Horňácka od 17. do 19. století. Procházet můžete usedlostmi, technickými stavbami, vinohradnickými búdami i lučním hospodářstvím jednotlivých mikroregionů. Muzeum často oživují folklorní pořady a řemeslné ukázky. Symbolická tečka za cestou Slováckem, kousek od hranice s Bílými Karpaty.', 48.9043, 17.31267, 'https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%A1%C5%BEnice%20-%20Veselsk%C3%A1%20br%C3%A1na%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Str%C3%A1%C5%BEnice%20-%20Veselsk%C3%A1%20br%C3%A1na%20(1).JPG"}'::text[], 7),
    (v_route, 'Restaurace: Pivovar Černý Orel (Kroměříž)', 'Oceňovaný pivovarský hotel a restaurace přímo v historickém centru Kroměříže, pár kroků od arcibiskupského zámku. Kuchyně staví na moravských tradicích a lokálních surovinách, k tomu vlastní pivo s medailemi ze Zlaté pivní pečeti a čokoládovna. Skvělé místo pro nocleh a večeři na rozhraní obou dní. Doporučujeme rezervaci, zvlášť o víkendech.', 49.29889, 17.3925, 'https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Krom%C4%9B%C5%99%C3%AD%C5%BE.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/N%C3%A1m%C4%9Bst%C3%AD%20Krom%C4%9B%C5%99%C3%AD%C5%BE.JPG"}'::text[], 8),
    (v_route, 'Restaurace: Makalu (Uherské Hradiště)', 'Vyhlášená indicko-nepálská restaurace v Uherském Hradišti s hodnocením kolem 4,6 hvězdy a stovkami spokojených recenzí. Nabízí voňavá kari, tandoori speciality i vegetariánská jídla v nastavitelné míře pálivosti. Vítaná změna od klasické české kuchyně během druhého dne na Slovácku. Leží jen kousek od trasy mezi Velehradem a Spytihněví.', 49.06972, 17.45944, 'https://commons.wikimedia.org/wiki/Special:FilePath/Uhersk%C3%A9%20Hradi%C5%A1t%C4%9B,%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD%2017.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Uhersk%C3%A9%20Hradi%C5%A1t%C4%9B,%20Masarykovo%20n%C3%A1m%C4%9Bst%C3%AD%2017.JPG"}'::text[], 9);
  insert into public.routes
