  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Karlovy Vary – Mlýnská kolonáda', 'Mlýnská kolonáda je nejvýstavnější lázeňská kolonáda Karlových Varů, kterou v novorenesančním slohu navrhl architekt Josef Zítek v letech 1871–1881. Pod jejími sloupovými arkádami vyvěrá pět léčivých pramenů a horní balustrádu zdobí sochy dvanácti měsíců. Je ideálním startem procházky historickým lázeňským centrem podél řeky Teplé.', 50.22289, 12.88389, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ml%C3%BDnsk%C3%A1%20kolon%C3%A1da%20Karlovy%20Vary.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ml%C3%BDnsk%C3%A1%20kolon%C3%A1da%20Karlovy%20Vary.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ml%C3%BDnsk%C3%A1%20kolon%C3%A1da%20in%20Karlovy%20Vary.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ml%C3%BDnsk%C3%A1%20kolon%C3%A1da%20002.JPG"}'::text[], 0),
    (v_route, 'Rozhledna Diana (Karlovy Vary)', 'Rozhledna Diana stojí na Výšině přátelství přímo nad centrem Karlových Varů ve výšce zhruba 560 metrů nad mořem. Na vyhlídkovou plošinu ve 40metrové věži vyjedete výtahem nebo vystoupáte po schodech a odmění vás kruhový výhled na celé lázeňské město i okolní lesy. K rozhledně se pohodlně dostanete lanovkou od hotelu Imperial.', 50.21896, 12.87229, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Diana%20Karlovy%20Vary.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Diana%20Karlovy%20Vary.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rozhledna%20Diana%20(Karlovy%20Vary)%204.JPG"}'::text[], 1),
    (v_route, 'Restaurace: Ventura Pub Evropák (Karlovy Vary)', 'Ventura Pub Evropák v karlovarské čtvrti Tuhnice patří k nejlépe hodnoceným restauracím ve městě (hodnocení kolem 4,7 na Googlu). Kombinuje poctivou českou kuchyni s moderním pojetím a nabízí velkou letní terasu s dvěma sty místy. Je vhodnou zastávkou na oběd na konci prvního dne v okolí Karlových Varů.', 50.22795, 12.8503, 'https://commons.wikimedia.org/wiki/Special:FilePath/KarlovyVary.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/KarlovyVary.JPG"}'::text[], 2),
    (v_route, 'Jáchymov – Královská mincovna', 'Renesanční Královská mincovna z let 1534–1536 stojí na rohu Mincovní ulice a náměstí Republiky v hornickém Jáchymově. Právě zde se razily proslulé stříbrné tolary, podle nichž dostal jméno i dolar. Dnes v budově sídlí muzeum přibližující slávu jáchymovského stříbra i pozdější těžbu uranu.', 50.37325, 12.91272, 'https://commons.wikimedia.org/wiki/Special:FilePath/Joachimsthal-2007-09-04-Muzeum.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Joachimsthal-2007-09-04-Muzeum.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%A1chymov%20b%C3%BDval%C3%A1%20mincovna%20srpen%202019%20(1).jpg"}'::text[], 3),
    (v_route, 'Boží Dar', 'Boží Dar je nejvýše položené město České republiky i střední Evropy, leží v 1028 metrech nad mořem u samé hranice se Saskem. Renesanční obdélníkové náměstí s pozdně klasicistní radnicí je vstupní branou do krušnohorských plání a v zimě do lyžařského areálu. V okolí najdete naučné stezky, rašeliniště a Ježíškovu cestu.', 50.41145, 12.92183, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bo%C5%BE%C3%AD%20Dar%2C%20kostel%20od%20n%C3%A1m%C4%9Bst%C3%AD.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bo%C5%BE%C3%AD%20Dar%2C%20kostel%20od%20n%C3%A1m%C4%9Bst%C3%AD.JPG"}'::text[], 4),
    (v_route, 'Klínovec – rozhledna', 'Klínovec je s 1244 metry nejvyšší horou Krušných hor. Kamennou osmibokou rozhlednu, dokončenou roku 2013 jako repliku věže z roku 1884, doplňuje horský hotel, lanovka a rozsáhlý lyžařský areál. Za dobrého počasí dohlédnete daleko do Saska i do českého vnitrozemí.', 50.39583, 12.9675, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%ADnovec%2C%20vrchol.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%ADnovec%2C%20vrchol.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%ADnovec%2C%20horsk%C3%BD%20hotel%20a%20rozhledna%20(02).jpg"}'::text[], 5),
    (v_route, 'Hrad Loket', 'Mohutný románsko-gotický hrad Loket se tyčí na žulovém ostrohu, který ze tří stran obtéká řeka Ohře. Bývá označován za klíč ke Království českému a patří k nejstarším a nejzachovalejším hradům u nás. Návštěvníky lákají hradní expozice, vyhlídková věž a malebné historické městečko pod hradbami.', 50.1871, 12.75428, 'https://commons.wikimedia.org/wiki/Special:FilePath/Loket%20Castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Loket%20Castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Loket%20-%20Loket.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Loket%20hrad%20(6).jpg"}'::text[], 6),
    (v_route, 'Bečov nad Teplou – hrad a zámek (relikviář sv. Maura)', 'Areál státního hradu a zámku Bečov nad Teplou spojuje gotický hrad, renesanční palác i barokní zámek nad údolím řeky Teplé. Jeho největším pokladem je relikviář svatého Maura, románská zlatnická práce z první třetiny 13. století, která je po korunovačních klenotech druhou nejcennější movitou památkou v Česku. Skvost byl objeven roku 1985 pod podlahou hradní kaple, kde byl ukryt po druhé světové válce.', 50.08586, 12.83973, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zimn%C3%AD%20hrad%20Be%C4%8Dov.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zimn%C3%AD%20hrad%20Be%C4%8Dov.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Reliquary%20of%20St.%20Maurus%20-%201.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Reliquary%20of%20St.%20Maurus%20-%202.JPG"}'::text[], 7),
    (v_route, 'Kladská – rašeliniště a naučná stezka', 'Osada Kladská leží v srdci CHKO Slavkovský les zhruba devět kilometrů severně od Mariánských Lázní. Zdejší národní přírodní rezervace chrání rozsáhlá vrchovištní rašeliniště, jejichž tajemným pralesním i vodním světem prochází pohodlná povalová naučná stezka dlouhá asi 1,6 kilometru. Trasa vede kolem malebného Kladského rybníka a je sjízdná i pro kočárky.', 50.02555, 12.66792, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kladsk%C3%BD%20rybn%C3%ADk.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kladsk%C3%BD%20rybn%C3%ADk.jpg"}'::text[], 8),
    (v_route, 'Mariánské Lázně – Zpívající fontána', 'Zpívající fontána je proslulou dominantou lázeňské kolonády v Mariánských Lázních u pomníku opata Reitenbergera. Její vodní chrliče tančí v pravidelných intervalech do rytmu klasické i moderní hudby a večer je fontána barevně nasvícena. Kolonáda z litinových konstrukcí patří k nejkrásnějším v Evropě a je součástí památky UNESCO Slavná evropská lázeňská města.', 49.968, 12.7085, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mari%C3%A1nsk%C3%A9%20L%C3%A1zn%C4%9B-kolon%C3%A1da-zp%C3%ADvaj%C3%ADc%C3%AD%20font%C3%A1na.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mari%C3%A1nsk%C3%A9%20L%C3%A1zn%C4%9B-kolon%C3%A1da-zp%C3%ADvaj%C3%ADc%C3%AD%20font%C3%A1na.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Marienbad%20(CZ)%20Kolonaden.JPG"}'::text[], 9),
    (v_route, 'Restaurace: Gourmet Restaurant Villa Patriot (Mariánské Lázně)', 'Gourmet Restaurant Villa Patriot v centru Mariánských Lázní patří k nejlépe hodnoceným podnikům ve městě (kolem 4,7 na Googlu) a získal ocenění jedné čepice v průvodci Gault&Millau. Kuchyně staví na kvalitních regionálních surovinách a spojuje francouzskou a českou gastronomii. Je vhodnou zastávkou na oběd druhého dne jen pár kroků od zpívající fontány.', 49.9649, 12.7059, 'https://commons.wikimedia.org/wiki/Special:FilePath/Marienbad%20(CZ)%20Kolonaden.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Marienbad%20(CZ)%20Kolonaden.JPG"}'::text[], 10),
    (v_route, 'Františkovy Lázně – Františkův pramen', 'Františkovy Lázně jsou nejmenší z proslulé západočeské lázeňské trojice a vynikají klasicistní architekturou ve žlutobílých barvách. Ikonický Františkův pramen vyvěrá v empírovém pavilonu na Národní třídě, který byl vystavěn roku 1832 jako klasicistní tempieto s dórskými sloupy. Lázně jsou spolu s Karlovými Vary a Mariánskými Lázněmi zapsány na seznamu UNESCO.', 50.11957, 12.35107, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fr%20l%C3%A1zn%C4%9B%20Franti%C5%A1k%C5%AFv%20pramen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fr%20l%C3%A1zn%C4%9B%20Franti%C5%A1k%C5%AFv%20pramen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Socha%20Franti%C5%A1ka.JPG"}'::text[], 11);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Karlštejn', 'Gotický hrad založený roku 1348 císařem Karlem IV. patří k nejslavnějším a nejnavštěvovanějším hradům v Česku. Sloužil jako pokladnice říšských korunovačních klenotů a svatých ostatků, jeho srdcem je nádherně zdobená kaple svatého Kříže. Hrad malebně ční nad stejnojmennou vesničkou v údolí Berounky a je skvělým startem celého okruhu.', 49.93914, 14.18842, 'https://commons.wikimedia.org/wiki/Special:FilePath/Karl%C5%A1tejn.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Karl%C5%A1tejn.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/27%20Karl%C5%A1tejn%20hrad%20SV.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Karl%C5%A1tejn,%20pohled%20od%20jihu.JPG"}'::text[], 0),
    (v_route, 'Koněpruské jeskyně', 'Největší jeskynní systém v Čechách se nachází v srdci Českého krasu jen pár kilometrů jižně od Berouna. Návštěvníky okouzlí bohatá krápníková výzdoba a unikátní Koněpruské růžice. V patrech jeskyně byla objevena i tajná penězokazecká dílna z 15. století. Prohlídka nabízí příjemné osvěžení a je vhodná i pro děti.', 49.91512, 14.06742, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kon%C4%9Bprusk%C3%A9%20jeskyn%C4%9B%20(04).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kon%C4%9Bprusk%C3%A9%20jeskyn%C4%9B%20(04).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Konepruske%20jeskyne.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kon%C4%9Bprusk%C3%A9%20jeskyn%C4%9B.jpg"}'::text[], 1),
    (v_route, 'Beroun (medvědi na Městské hoře)', 'Město Beroun leží v malebném údolí na soutoku Berounky a Litavky a v jeho znaku najdete medvěda. Na zalesněné Městské hoře je volně přístupné medvědárium, kde žili proslulí medvědi Kuba, Vojta a Matěj z televizního Večerníčku. Nad výběhem stojí rozhledna s pěkným výhledem na město i okolní kopce. Zastávka je ideální na svačinu i protažení po jízdě.', 49.96322, 14.06607, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beroun%20M%C4%9Bstsk%C3%A1%20hora%20SZ.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beroun%20M%C4%9Bstsk%C3%A1%20hora%20SZ.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Beroun,%20n%C3%A1m%C4%9Bst%C3%AD.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Konírna Nižbor (Nižbor)', 'Oblíbená restaurace v Nižboru poblíž zámku a řeky Berounky je skvělou zastávkou na oběd zhruba v polovině okruhu. Nabízí poctivou českou i mezinárodní kuchyni a příjemné posezení, hosté ji hodnotí velmi vysoko. Ideální místo, kde nabrat síly před další částí cesty na Křivoklát.', 49.99969, 13.99917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nizbor%20sklarny.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nizbor%20sklarny.JPG"}'::text[], 3),
    (v_route, 'Nižbor (sklárna Rückl a keltské oppidum)', 'Zámek Nižbor nad Berounkou skrývá pozůstatky gotického hradu založeného Přemyslem Otakarem II. a dnes připomíná keltskou minulost Čech. Nedaleko na vrchu Hradiště leželo jedno z nejvýznamnějších keltských oppid Stradonice, kolem něhož vede naučná stezka. V obci sídlí i tradiční rodinná sklárna Rückl, kde se už přes 170 let vyrábí broušený křišťál. Kombinace historie a sklářského řemesla dělá z Nižboru zajímavou zastávku.', 49.99969, 13.99917, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nizbor%20zamek%20slunecni%20hodiny%209120.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nizbor%20zamek%20slunecni%20hodiny%209120.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Nizbor%20sklarny.JPG"}'::text[], 4),
    (v_route, 'Hrad Křivoklát', 'Jeden z nejstarších a nejvýznamnějších českých hradů se tyčí v hlubokých lesích chráněné krajinné oblasti Křivoklátsko. Založen byl už ve 12. století jako lovecké sídlo přemyslovských a lucemburských panovníků. Uvnitř zaujme gotická kaple, velký sál a rozsáhlá hradní knihovna. Cesta údolím Berounky sem patří k nejkrásnějším úsekům celého okruhu.', 50.0376, 13.8727, 'https://commons.wikimedia.org/wiki/Special:FilePath/Krivoklat%20castle%20Czech%20Republic.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Krivoklat%20castle%20Czech%20Republic.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20K%C5%99ivokl%C3%A1t%20(K%C5%99ivokl%C3%A1t).JPG"}'::text[], 5),
    (v_route, 'Zámek Konopiště', 'Honosný zámek u Benešova byl posledním sídlem následníka trůnu Františka Ferdinanda d''Este, jehož atentát v Sarajevu roku 1914 rozpoutal první světovou válku. Zámek proslul bohatými sbírkami zbraní, loveckých trofejí a uměleckých děl. Obklopuje ho rozlehlý anglický park s růžovou zahradou a rybníky. Prohlídka interiérů i procházka parkem stojí za delší zastavení.', 49.779, 14.656, 'https://commons.wikimedia.org/wiki/Special:FilePath/Konopi%C5%A1t%C4%9B%20castle.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Konopi%C5%A1t%C4%9B%20castle.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Overview%20of%20Konopi%C5%A1t%C4%9B%20castle,%20Konopi%C5%A1t%C4%9B,%20Bene%C5%A1ov,%20Bene%C5%A1ov%20District.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Konopi%C5%A1t%C4%9B,%202021%20(73).jpg"}'::text[], 6),
    (v_route, 'Hrad Kokořín', 'Romantický gotický hrad se vypíná na pískovcovém ostrohu v malebném Kokořínském dole v CHKO Kokořínsko. Postaven byl ve 14. století a po staletích zpustnutí byl na počátku 20. století citlivě obnoven do dnešní podoby. Z vyhlídkové věže je nádherný pohled do zalesněného údolí a na okolní skalní útvary. Okolní kraj vás uchvátí bludišti pískovcových skal a klidnou přírodou.', 50.43, 14.567, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kokorin%20hrad%20panorama.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kokorin%20hrad%20panorama.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Hrad-Koko%C5%99%C3%ADn-z-vyhl%C3%ADdky-v-zat%C3%A1%C4%8Dce-silnice2018c.jpg"}'::text[], 7);
