  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kutná Hora – chrám sv. Barbory (UNESCO)', 'Vrcholně gotický chrám sv. Barbory je nejvýznamnější památkou Kutné Hory a od roku 1995 je zapsán na seznamu světového dědictví UNESCO. Katedrálu nechali od konce 14. století stavět bohatí kutnohorští havíři jako výraz svého bohatství ze stříbrných dolů. Unikátní síťová klenba a strmé stanové střechy tvoří nezaměnitelnou siluetu města. Chrám je dokonalým startem výletu za historií i přírodou.', 49.94494, 15.26336, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kutna%20Hora%20CZ%20St%20Barbara%20Cathedral%20front%20view%2002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kutna%20Hora%20CZ%20St%20Barbara%20Cathedral%20front%20view%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Kutna%20Hora%20chram%20sv%20Barbory%20z%20bastionu.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Chr%C3%A1m%20svat%C3%A9%20Barbory%20v%20Kutn%C3%A9%20Ho%C5%99e%2004.JPG"}'::text[], 0),
    (v_route, 'Sedlec – kostnice', 'Kostnice v Sedlci pod hřbitovním kostelem Všech svatých patří k nejnavštěvovanějším a nejtajemnějším místům Česka. Interiér je vyzdoben ostatky přibližně 40 tisíc lidí, které v 19. století umělecky uspořádal řezbář František Rint. Nejslavnějším dílem je obrovský lustr sestavený ze všech kostí lidského těla. Návštěva tohoto jedinečného místa nenechá nikoho chladným.', 49.96194, 15.28833, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ossuary%20in%20Sedlec.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ossuary%20in%20Sedlec.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sedlec%20Ossuary%20chandelier.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Sedlec%20Ossuary%20bone%20pyramid%201.JPG"}'::text[], 1),
    (v_route, 'Zámek Kačina', 'Zámek Kačina u Kutné Hory je nejvýznamnější empírovou stavbou v Česku, postavenou počátkem 19. století pro rod Chotků. Rozlehlá stavba s výraznou kupolí je obklopena krajinářským anglickým parkem. Dnes zde sídlí Národní zemědělské muzeum s bohatými expozicemi. Klidné okolí a vzrostlé aleje lákají k zastávce a procházce.', 49.982, 15.346, 'https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Ka%C4%8Dina%20s%20pr%C5%AF%C4%8Del%C3%ADm.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Ka%C4%8Dina%20s%20pr%C5%AF%C4%8Del%C3%ADm.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Z%C3%A1mek%20Ka%C4%8Dina%20-%20%C5%A1tukov%C3%A1%20v%C3%BDzdoba%20fas%C3%A1d%2007.jpg"}'::text[], 2),
    (v_route, 'Zámek Žleby', 'Romantický zámek Žleby vznikl přestavbou původního gotického hradu do podoby anglické neogotiky v polovině 19. století. Interiéry patří k nejlépe dochovaným v Česku a nabízejí bohaté sbírky zbraní, nábytku a loveckých trofejí. V areálu se nachází i obora s bílými jeleny. Malebné městečko pod zámkem je příjemným místem pro krátkou zastávku.', 49.88781, 15.48365, 'https://commons.wikimedia.org/wiki/Special:FilePath/19790529105MNR%20Zleby%20(CSSR)%20Schlo%C3%9F.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/19790529105MNR%20Zleby%20(CSSR)%20Schlo%C3%9F.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/%C5%BDleby%2C%20z%C3%A1mek.jpg"}'::text[], 3),
    (v_route, 'Hrad Lichnice', 'Zřícenina raně gotického hradu Lichnice se tyčí na skalnatém ostrohu na západním okraji Železných hor nad obcí Podhradí. Královský hrad byl založen ve 13. století rodem pánů z Lichtenburka a po třicetileté válce zpustl. Z torza hradní věže dnes vystupuje ocelová rozhledna Milada s dalekými výhledy do kraje. K hradu vede pohodlná stezka a je odměnou pro milovníky historie i panoramat.', 49.87923, 15.58627, 'https://commons.wikimedia.org/wiki/Special:FilePath/Podhrad%C3%AD%20(T%C5%99emo%C5%A1nice)%20-%20hrad%20Lichnice%2C%20rozhledna.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Podhrad%C3%AD%20(T%C5%99emo%C5%A1nice)%20-%20hrad%20Lichnice%2C%20rozhledna.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lichnice%2C%20hrad%20(09).jpg"}'::text[], 4),
    (v_route, 'Přehrada Seč', 'Vodní nádrž Seč vznikla ve 30. letech 20. století přehrazením řeky Chrudimky a je jednou z nejkrásnějších přehrad v Železných horách. Klikaté břehy, zalesněné svahy a nad hladinou se tyčící zřícenina hradu Oheb tvoří romantickou scenérii. Přehrada je vyhledávaným místem k rekreaci, koupání i projížďkám lodí. Serpentiny kolem nádrže patří k nejhezčím motorkářským úsekům trasy.', 49.82473, 15.64554, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Se%C4%8D%2C%20CZ140322-019.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Se%C4%8D%2C%20CZ140322-019.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Se%C4%8D%2C%20pohled%20na%20n%C3%A1dr%C5%BE%20z%20Ohebu%20(2017-07-03%3B%2002).jpg"}'::text[], 5),
    (v_route, 'Restaurace: Hostinec Pod Drnem (Seč)', 'Hostinec Pod Drnem nad hladinou přehrady Seč je oblíbenou zastávkou pro motorkáře i turisty s trempskou atmosférou a nádherným výhledem na vodu. Nabízí teplá jídla, kamennou udírnu, zastřešené ohniště a gril, díky čemuž patří k nejlépe hodnoceným podnikům v okolí. Přátelská obsluha a klidné prostředí jsou ideální pro polední pauzu v polovině trasy.', 49.81571, 15.65243, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Se%C4%8D%2C%20CZ140322-019.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Se%C4%8D%2C%20CZ140322-019.jpg"}'::text[], 6),
    (v_route, 'Památník Ležáky', 'Pietní památník Ležáky připomíná osadu vypálenou nacisty v červnu 1942 jako odplatu za pomoc parašutistům operace Anthropoid. Všichni dospělí obyvatelé byli zavražděni a osada srovnána se zemí. V rozvlněné krajině dnes stojí žulové kameny na místech, kde stávala jednotlivá stavení. Tiché a dojemné místo je připomínkou tragických dějin 20. století.', 49.831, 15.901, 'https://commons.wikimedia.org/wiki/Special:FilePath/Le%C5%BE%C3%A1ky%20III.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Le%C5%BE%C3%A1ky%20III.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pam%C3%A1tn%C3%ADk%20Le%C5%BE%C3%A1ky%20(005).jpg"}'::text[], 7),
    (v_route, 'Chrudim – Muzeum loutkářských kultur', 'Chrudim je proslulá jako město loutkářství a každoročně zde probíhá festival Loutkářská Chrudim. Muzeum loutkářských kultur sídlí v překrásném renesančním Mydlářovském domě z 16. století s charakteristickou vížkou ve tvaru minaretu. Ve sbírkách je přes osm tisíc loutek včetně slavných marionet. Historické jádro města s náměstím je příjemným zakončením celodenního okruhu.', 49.95059, 15.79522, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chrudim%20-%20Mydl%C3%A1%C5%99ovsk%C3%BD%20d%C5%AFm.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chrudim%20-%20Mydl%C3%A1%C5%99ovsk%C3%BD%20d%C5%AFm.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chrudim-Mydl%C3%A1%C5%99ovsk%C3%BD-d%C5%AFm-z-Ko%C5%BEelu%C5%BEsk%C3%A9-ulice2014.jpg"}'::text[], 8);
